(window.JUR_IMPORT = window.JUR_IMPORT || []).push([{"tribunal": "STF-SV", "n": "2", "texto": "É inconstitucional a lei ou ato normativo Estadual ou Distrital que disponha sobre sistemas de consórcios e sorteios, inclusive bingos e loterias.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "3", "texto": "Nos processos perante o Tribunal de Contas da União asseguram-se o contraditório e a ampla defesa quando da decisão puder resultar anulação ou revogação de ato administrativo que beneficie o interessado, excetuada a apreciação da legalidade do ato de concessão inicial de aposentadoria, reforma e pensão.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "4", "texto": "Salvo nos casos previstos na Constituição, o salário mínimo não pode ser usado como indexador de base de cálculo de vantagem de servidor público ou de empregado, nem ser substituído por decisão judicial.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "5", "texto": "A falta de defesa técnica por advogado no processo administrativo disciplinar não ofende a Constituição.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "6", "texto": "Não viola a Constituição o estabelecimento de remuneração inferior ao salário mínimo para as praças prestadoras de serviço militar inicial.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "7", "texto": "A norma do § 3º do artigo 192 da Constituição, revogada pela Emenda Constitucional 40/2003, que limitava a taxa de juros reais a 12% ao ano, tinha sua aplicação condicionada à edição de lei complementar.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "8", "texto": "São inconstitucionais o parágrafo único do artigo 5º do Decreto-Lei 1.569/1977 e os artigos 45 e 46 da Lei 8.212/1991, que tratam da prescrição e decadência do crédito tributário.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "9", "texto": "O disposto no artigo 127 da Lei 7.210/1984 (Lei de Execução Penal) foi recebido pela ordem constitucional vigente, e não se lhe aplica o limite temporal previsto no caput do artigo 58.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "10", "texto": "Viola a cláusula de reserva de plenário (CF, artigo 97) a decisão de órgão fracionário de tribunal que, embora não declare expressamente a inconstitucionalidade de lei ou ato normativo do Poder Público, afasta sua incidência, no todo ou em parte.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "11", "texto": "Só é lícito o uso de algemas em casos de resistência e de fundado receio de fuga ou de perigo à integridade física própria ou alheia, por parte do preso ou de terceiros, justificada a excepcionalidade por escrito, sob pena de responsabilidade disciplinar, civil e penal do agente ou da autoridade e de nulidade da prisão ou do ato processual a que se refere, sem prejuízo da responsabilidade civil do Estado.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "12", "texto": "A cobrança de taxa de matrícula nas universidades públicas viola o disposto no art. 206, IV, da Constituição Federal.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "13", "texto": "A nomeação de cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade, até o terceiro grau, inclusive, da autoridade nomeante ou de servidor da mesma pessoa jurídica investido em cargo de direção, chefia ou assessoramento, para o exercício de cargo em comissão ou de confiança ou, ainda, de função gratificada na administração pública direta e indireta em qualquer dos poderes da União, dos Estados, do Distrito Federal e dos Municípios, compreendido o ajuste mediante designações recíprocas, viola a Constituição Federal.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "14", "texto": "É direito do defensor, no interesse do representado, ter acesso amplo aos elementos de prova que, já documentados em procedimento investigatório realizado por órgão com competência de polícia judiciária, digam respeito ao exercício do direito de defesa.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "15", "texto": "O cálculo de gratificações e outras vantagens do servidor público não incide sobre o abono utilizado para se atingir o salário mínimo.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "16", "texto": "Os artigos 7º, IV, e 39, § 3º (redação da EC 19/98), da Constituição, referem-se ao total da remuneração percebida pelo servidor público.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "17", "texto": "Durante o período previsto no parágrafo 1º do artigo 100 da Constituição, não incidem juros de mora sobre os precatórios que nele sejam pagos.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "18", "texto": "A dissolução da sociedade ou do vínculo conjugal, no curso do mandato, não afasta a inelegibilidade prevista no § 7º do artigo 14 da Constituição Federal.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "19", "texto": "A taxa cobrada exclusivamente em razão dos serviços públicos de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis não viola o artigo 145, II, da Constituição Federal.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "20", "texto": "A Gratificação de Desempenho de Atividade Técnico-Administrativa - GDATA, instituída pela Lei 10.404/2002, deve ser deferida aos inativos nos valores correspondentes a 37,5 (trinta e sete vírgula cinco) pontos no período de fevereiro a maio de 2002 e, nos termos do artigo 5º, parágrafo único, da Lei 10.404/2002, no período de junho de 2002 até a conclusão dos efeitos do último ciclo de avaliação a que se refere o artigo 1º da Medida Provisória 198/2004, a partir da qual passa a ser de 60 (sessenta) pontos.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "21", "texto": "É inconstitucional a exigência de depósito ou arrolamento prévios de dinheiro ou bens para admissibilidade de recurso administrativo.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "22", "texto": "A Justiça do Trabalho é competente para processar e julgar as ações de indenização por danos morais e patrimoniais decorrentes de acidente de trabalho propostas por empregado contra empregador, inclusive aquelas que ainda não possuíam sentença de mérito em primeiro grau quando da promulgação da Emenda Constitucional 45/2004.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "23", "texto": "A Justiça do Trabalho é competente para processar e julgar ação possessória ajuizada em decorrência do exercício do direito de greve pelos trabalhadores da iniciativa privada.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "24", "texto": "Não se tipifica crime material contra a ordem tributária, previsto no art. 1º, incisos I a IV, da Lei 8.137/1990, antes do lançamento definitivo do tributo.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "25", "texto": "É ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade de depósito.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "26", "texto": "Para efeito de progressão de regime no cumprimento de pena por crime hediondo, ou equiparado, o juízo da execução observará a inconstitucionalidade do art. 2º da Lei 8.072, de 25 de julho de 1990, sem prejuízo de avaliar se o condenado preenche, ou não, os requisitos objetivos e subjetivos do benefício, podendo determinar, para tal fim, de modo fundamentado, a realização de exame criminológico.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "27", "texto": "Compete à Justiça Estadual julgar causas entre consumidor e concessionária de serviço público de telefonia, quando a ANATEL não seja litisconsorte passiva necessária, assistente, nem opoente.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "28", "texto": "É inconstitucional a exigência de depósito prévio como requisito de admissibilidade de ação judicial na qual se pretenda discutir a exigibilidade de crédito tributário.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "29", "texto": "É constitucional a adoção, no cálculo do valor de taxa, de um ou mais elementos da base de cálculo própria de determinado imposto, desde que não haja integral identidade entre uma base e outra.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "30", "texto": "A Súmula Vinculante 30 está pendente de publicação.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "31", "texto": "É inconstitucional a incidência do imposto sobre serviços de qualquer natureza - ISS sobre operações de locação de bens móveis.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "32", "texto": "O ICMS não incide sobre alienação de salvados de sinistro pelas seguradoras.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "33", "texto": "Aplicam-se ao servidor público, no que couber, as regras do regime geral da previdência social sobre aposentadoria especial de que trata o artigo 40, § 4º, inciso III da Constituição Federal, até a edição de lei complementar específica.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "34", "texto": "A Gratificação de Desempenho de Atividade de Seguridade Social e do Trabalho - GDASST, instituída pela Lei 10.483/2002, deve ser estendida aos inativos no valor correspondente a 60 (sessenta) pontos, desde o advento da Medida Provisória 198/2004, convertida na Lei 10.971/2004, quando tais inativos façam jus à paridade constitucional (EC 20/1998, 41/2003 e 47/2005).", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "35", "texto": "A homologação da transação penal prevista no artigo 76 da Lei 9.099/1995 não faz coisa julgada material e, descumpridas suas cláusulas, retoma-se a situação anterior, possibilitando-se ao Ministério Público a continuidade da persecução penal mediante oferecimento de denúncia ou requisição de inquérito policial.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "36", "texto": "Compete à Justiça Federal comum processar e julgar civil denunciado pelos crimes de falsificação e de uso de documento falso quando se tratar de falsificação da Caderneta de Inscrição e Registro (CIR) ou de Carteira de Habilitação de Amador (CHA), ainda que expedidas pela Marinha do Brasil.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "37", "texto": "Não cabe ao Poder Judiciário, que não tem função legislativa, aumentar vencimentos de servidores públicos sob o fundamento de isonomia.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "38", "texto": "É competente o Município para fixar o horário de funcionamento de estabelecimento comercial.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "39", "texto": "Compete privativamente à União legislar sobre vencimentos dos membros das polícias civil e militar e do corpo de bombeiros militar do Distrito Federal.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "40", "texto": "A contribuição confederativa de que trata o art. 8º, IV, da Constituição Federal, só é exigível dos filiados ao sindicato respectivo.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "41", "texto": "O serviço de iluminação pública não pode ser remunerado mediante taxa.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "42", "texto": "É inconstitucional a vinculação do reajuste de vencimentos de servidores estaduais ou municipais a índices federais de correção monetária.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "43", "texto": "É inconstitucional toda modalidade de provimento que propicie ao servidor investir-se, sem prévia aprovação em concurso público destinado ao seu provimento, em cargo que não integra a carreira na qual anteriormente investido.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "44", "texto": "Só por lei se pode sujeitar a exame psicotécnico a habilitação de candidato a cargo público.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "45", "texto": "A competência constitucional do Tribunal do Júri prevalece sobre o foro por prerrogativa de função estabelecido exclusivamente pela Constituição Estadual.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "46", "texto": "A definição dos crimes de responsabilidade e o estabelecimento das respectivas normas de processo e julgamento são de competência legislativa privativa da União.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "47", "texto": "Os honorários advocatícios incluídos na condenação ou destacados do montante principal devido ao credor consubstanciam verba de natureza alimentar cuja satisfação ocorrerá com a expedição de precatório ou requisição de pequeno valor, observada ordem especial restrita aos créditos dessa natureza.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "48", "texto": "Na entrada de mercadoria importada do exterior, é legítima a cobrança do ICMS por ocasião do desembaraço aduaneiro.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "49", "texto": "Ofende o princípio da livre concorrência lei municipal que impede a instalação de estabelecimentos comerciais do mesmo ramo em determinada área.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "50", "texto": "Norma legal que altera o prazo de recolhimento de obrigação tributária não se sujeita ao princípio da anterioridade.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "51", "texto": "O reajuste de 28,86%, concedido aos servidores militares pelas Leis 8622/1993 e 8627/1993, estende-se aos servidores civis do poder executivo, observadas as eventuais compensações decorrentes dos reajustes diferenciados concedidos pelos mesmos diplomas legais.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "52", "texto": "Ainda quando alugado a terceiros, permanece imune ao IPTU o imóvel pertencente a qualquer das entidades referidas pelo art. 150, VI, \"c\", da Constituição Federal, desde que o valor dos aluguéis seja aplicado nas atividades para as quais tais entidades foram constituídas.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "53", "texto": "A competência da Justiça do Trabalho prevista no art. 114, VIII, da Constituição Federal alcança a execução de ofício das contribuições previdenciárias relativas ao objeto da condenação constante das sentenças que proferir e acordos por ela homologados.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "54", "texto": "A medida provisória não apreciada pelo congresso nacional podia, até a Emenda Constitucional 32/2001, ser reeditada dentro do seu prazo de eficácia de trinta dias, mantidos os efeitos de lei desde a primeira edição.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "55", "texto": "O direito ao auxílio-alimentação não se estende aos servidores inativos.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "56", "texto": "A falta de estabelecimento penal adequado não autoriza a manutenção do condenado em regime prisional mais gravoso, devendo-se observar, nessa hipótese, os parâmetros fixados no RE 641.320/RS.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "58", "texto": "Inexiste direito a crédito presumido de IPI relativamente à entrada de insumos isentos, sujeitos à alíquota zero ou não tributáveis, o que não contraria o princípio da não cumulatividade.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "59", "texto": "É impositiva a fixação do regime aberto e a substituição da pena privativa de liberdade por restritiva de direitos quando reconhecida a figura do tráfico privilegiado (art. 33, § 4º, da Lei 11.343/06) e ausentes vetores negativos na primeira fase da dosimetria (art. 59 do CP), observados os requisitos do art. 33, § 2º, alínea c, e do art. 44, ambos do Código Penal.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "60", "texto": "O pedido e a análise administrativos de fármacos na rede pública de saúde, a judicialização do caso, bem ainda seus desdobramentos (administrativos e jurisdicionais), devem observar os termos dos 3 (três) acordos interfederativos (e seus fluxos) homologados pelo Supremo Tribunal Federal, em governança judicial colaborativa, no tema 1.234 da sistemática da repercussão geral RE 1.366.243.", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "61", "texto": "46. Porém, para fins de reduzir e racionalizar, tanto quanto possível, a judicialização nessas situações, proponho 5 (cinco) requisitos cumulativos que devem ser observados pelo Poder Judiciário para o deferimento de uma prestação de saúde. São eles: (i) a incapacidade financeira do requerente para arcar com o custo correspondente, (ii) a demonstração de que a não incorporação do medicamento não resultou de decisão expressa dos órgãos competentes, (iii) a inexistência de substituto terapêutico incorporado pelo SUS, (iv) a comprovação de eficácia do medicamento pleiteado à luz da medicina baseada em evidências, e (v) a propositura da demanda necessariamente em face da União. Ademais, deve-se exigir a observância de 1 (um) parâmetro procedimental relativo à realização de diálogo interinstitucional entre o Poder Judiciário e entes ou pessoas com expertise técnica na área da saúde (e.g., câmaras e núcleos de apoio técnico em saúde no âmbito dos tribunais, profissionais do SUS e CONITEC), para fins de aferir a presença dos requisitos de dispensação e determinar aos órgãos competentes, no caso de deferimento judicial do medicamento, que avaliem a possibilidade de sua incorporação pelo SUS. [ RE 566.471 , rel. min. Marco Aurélio , red. p/ o ac. min. Luís Roberto Barroso , P, j. 26-9-2024, DJE 28-11-2024.]", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "62", "texto": "a) Exigência de reserva de plenário para as situações de não-aplicação do art. 56 da Lei nº 9.430/96 , que revogou a isenção da COFINS para as sociedades prestadoras de serviços. b) Necessidade de lei complementar para a revogação da isenção da COFINS para as sociedades prestadoras de serviços. [ RE 377.457 , rel. min. Gilmar Mendes , P, j. 17-9-2008, DJE 19-12-2008, Tema 71 .]", "vinculante": true, "pub": ""}, {"tribunal": "STF-SV", "n": "63", "texto": "O tráfico privilegiado (art. 33, § 4º, da Lei 11.343/2006) não configura crime hediondo, afastando-se a aplicação dos parâmetros mais rigorosos de progressão de regime e de livramento condicional.", "vinculante": true, "pub": ""}, {"tribunal": "STF", "n": "1", "texto": "É vedada a expulsão de estrangeiro casado com brasileira, ou que tenha filho brasileiro, dependente da economia paterna.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "2", "texto": "Concede-se liberdade vigiada ao extraditando que estiver preso por prazo superior a sessenta dias.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "3", "texto": "A imunidade concedida a deputados estaduais é restrita à Justiça do Estado. (superada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "4", "texto": "Não perde a imunidade parlamentar o congressista nomeado Ministro de Estado. (cancelada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "5", "texto": "A sanção do projeto supre a falta de iniciativa do Poder Executivo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "6", "texto": "A revogação ou anulação, pelo Poder Executivo, de aposentadoria, ou qualquer outro ato aprovado pelo Tribunal de Contas, não produz efeitos antes de aprovada por aquele tribunal, ressalvada a competência revisora do Judiciário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "7", "texto": "Sem prejuízo de recurso para o Congresso, não é exequível contrato administrativo a que o Tribunal de Contas houver negado registro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "8", "texto": "Diretor de sociedade de economia mista pode ser destituído no curso do mandato.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "9", "texto": "Para o acesso de auditores ao Superior Tribunal Militar, só concorrem os de segunda entrância.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "10", "texto": "O tempo de serviço militar conta-se para efeito de disponibilidade e aposentadoria do servidor público estadual.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "11", "texto": "A vitaliciedade não impede a extinção do cargo, ficando o funcionário em disponibilidade, com todos os vencimentos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "12", "texto": "A vitaliciedade do professor catedrático não impede o desdobramento da cátedra.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "13", "texto": "A equiparação de extranumerário a funcionário efetivo, determinada pela Lei 2.284, de 9-8-1954, não envolve reestruturação, não compreendendo, portanto, os vencimentos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "14", "texto": "Não é admissível, por ato administrativo, restringir, em razão da idade, inscrição em concurso para cargo público.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "15", "texto": "Dentro do prazo de validade do concurso, o candidato aprovado tem direito à nomeação, quando o cargo for preenchido sem observância da classificação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "16", "texto": "Funcionário nomeado por concurso tem direito à posse.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "17", "texto": "A nomeação de funcionário sem concurso pode ser desfeita antes da posse.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "18", "texto": "Pela falta residual, não compreendida na absolvição pelo juízo criminal, é admissível a punição administrativa do servidor público.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "19", "texto": "É inadmissível segunda punição de servidor público, baseada no mesmo processo em que se fundou a primeira.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "20", "texto": "É necessário processo administrativo com ampla defesa, para demissão de funcionário admitido por concurso.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "21", "texto": "Funcionário em estágio probatório não pode ser exonerado nem demitido sem inquérito ou sem as formalidades legais de apuração de sua capacidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "22", "texto": "O estágio probatório não protege o funcionário contra a extinção do cargo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "23", "texto": "Verificados os pressupostos legais para o licenciamento da obra, não o impede a declaração de utilidade pública para desapropriação do imóvel, mas o valor da obra não se incluirá na indenização, quando a desapropriação for efetivada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "24", "texto": "Funcionário interino substituto é livremente demissível, mesmo antes de cessar a causa da substituição.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "25", "texto": "A nomeação a termo não impede a livre demissão, pelo Presidente da República, de ocupante de cargo dirigente de autarquia.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "26", "texto": "Os servidores do Instituto de Aposentadoria e Pensões dos Industriários não podem acumular a sua gratificação bienal com o adicional de tempo de serviço previsto no Estatuto dos Funcionários Civis da União.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "27", "texto": "Os servidores públicos não têm vencimentos irredutíveis, prerrogativa dos membros do Poder Judiciário e dos que lhes são equiparados.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "28", "texto": "O estabelecimento bancário é responsável pelo pagamento de cheque falso, ressalvadas as hipóteses de culpa exclusiva ou concorrente do correntista.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "29", "texto": "Gratificação devida a servidores do \"sistema fazendário\" não se estende aos dos Tribunais de Contas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "30", "texto": "Servidores de coletorias não têm direito à percentagem pela cobrança de contribuições destinadas à Petrobrás.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "31", "texto": "Para aplicação da Lei 1741, de 22-11-1952, soma-se o tempo de serviço ininterrupto em mais de um cargo em comissão.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "32", "texto": "Para aplicação da L. 1741, de 22-11-1952, soma-se o tempo de serviço ininterrupto em cargo em comissão e em função gratificada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "33", "texto": "A L. 1741, de 22-11-1952, é aplicável às autarquias federais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "34", "texto": "No Estado de São Paulo, funcionário eleito vereador fica licenciado por tôda a duração do mandato.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "35", "texto": "Em caso de acidente do trabalho ou de transporte, a concubina tem direito de ser indenizada pela morte do amásio, se entre êles não havia impedimento para o matrimônio.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "36", "texto": "Servidor vitalício está sujeito à aposentadoria compulsória, em razão da idade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "37", "texto": "Não tem direito de se aposentar pelo Tesouro Nacional o servidor que não satisfizer as condições estabelecidas na legislação do serviço público federal, ainda que aposentado pela respectiva instituição previdenciária, com direito, em tese, a duas aposentadorias.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "38", "texto": "Reclassificação posterior à aposentadoria não aproveita ao servidor aposentado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "39", "texto": "À falta de lei, funcionário em disponibilidade não pode exigir, judicialmente, o seu aproveitamento, que fica subordinado ao critério de conveniência da administração.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "40", "texto": "A elevação da entrância da Comarca não promove automaticamente o Juiz, mas não interrompe o exercício de suas funções na mesma Comarca.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "41", "texto": "Juízes preparadores ou substitutos não têm direito aos vencimentos da atividade fora dos períodos de exercício.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "42", "texto": "É legítima a equiparação de juízes do Tribunal de Contas, em direitos e garantias, aos membros do Poder Judiciário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "43", "texto": "Não contraria a Constituição Federal o art. 61 da Constituição de São Paulo, que equiparou os vencimentos do Ministério Público aos da Magistratura.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "44", "texto": "O exercício do cargo pelo prazo determinado na Lei 1.341, de 30-1-1951, art. 91, dá preferência para a nomeação interina de Procurador da República.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "45", "texto": "A estabilidade dos substitutos do Ministério Público Militar não confere direito aos vencimentos da atividade fora dos períodos de exercício.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "46", "texto": "Desmembramento de serventia de justiça não viola o princípio de vitaliciedade do serventuário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "47", "texto": "Reitor de universidade não é livremente demissível pelo presidente da república durante o prazo de sua investidura.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "48", "texto": "É legítimo o rodízio de docentes livres na substituição do professor catedrático.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "49", "texto": "A cláusula de inalienabilidade inclui a incomunicabilidade dos bens. Jurisprudência selecionada A pesquisa no banco de jurisprudência do STF não recuperou decisões com menção a este enunciado após a Constituição Federal de 1988.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "50", "texto": "A lei pode estabelecer condições para a demissão de extranumerário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "51", "texto": "Militar não tem direito a mais de duas promoções na passagem para a inatividade, ainda que por motivos diversos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "52", "texto": "A promoção de militar, vinculada à inatividade, pode ser feita, quando couber, a pôsto inexistente no quadro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "53", "texto": "A promoção de professor militar, vinculada à sua reforma, pode ser feita, quando couber, a pôsto inexistente no quadro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "54", "texto": "A reserva ativa do magistério militar não confere vantagens vinculadas à efetiva passagem para a inatividade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "55", "texto": "Militar da reserva está sujeito à pena disciplinar.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "56", "texto": "Militar reformado não está sujeito à pena disciplinar.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "57", "texto": "Militar inativo não tem direito ao uso do uniforme fora dos casos previstos em lei ou regulamento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "58", "texto": "É válida a exigência de média superior a quatro para aprovação em estabelecimento de ensino superior, consoante o respectivo regimento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "59", "texto": "Imigrante pode trazer, sem licença prévia, automóvel que lhe pertença desde mais de seis meses antes do seu embarque para o Brasil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "60", "texto": "Não pode o estrangeiro trazer automóvel quando não comprovada a transferência definitiva de sua residência para o Brasil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "61", "texto": "Brasileiro domiciliado no estrangeiro, que se transfere definitivamente para o Brasil, pode trazer automóvel licenciado em seu nome há mais de seis meses.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "62", "texto": "Não basta a simples estada no estrangeiro por mais de seis meses, para dar direito à trazida de automóvel com fundamento em transferência de residência.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "63", "texto": "É indispensável, para trazida de automóvel, a prova do licenciamento há mais de seis meses no país de origem.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "64", "texto": "É permitido trazer do estrangeiro, como bagagem, objetos de uso pessoal e doméstico, desde que, por sua quantidade e natureza, não induzam finalidade comercial.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "65", "texto": "A cláusula de aluguel progressivo anterior à Lei 3.494, de 19-12-1958, continua em vigor em caso de prorrogação legal ou convencional da locação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "66", "texto": "É legítima a cobrança do tributo que houver sido aumentado após o orçamento, mas antes do início do respectivo exercício financeiro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "67", "texto": "É inconstitucional a cobrança do tributo que houver sido criado ou aumentado no mesmo exercício financeiro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "68", "texto": "É legítima a cobrança, pelos Municípios, no exercício de 1961, de tributo estadual, regularmente criado ou aumentado, e que lhes foi transferido pela Emenda Constitucional 5, de 21-11-1961.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "69", "texto": "A Constituição estadual não pode estabelecer limite para o aumento de tributos municipais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "70", "texto": "É inadmissível a interdição de estabelecimento como meio coercitivo para cobrança de tributo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "71", "texto": "Embora pago indevidamente, não cabe restituição de tributo indireto.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "72", "texto": "No julgamento de questão constitucional, vinculada a decisão do Tribunal Superior Eleitoral, não estão impedidos os Ministros do Supremo Tribunal Federal que ali tenham funcionado no mesmo processo, ou no processo originário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "73", "texto": "A imunidade das autarquias, implicitamente contida no art. 31, V, a, da Constituição Federal, abrange tributos estaduais e municipais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "74", "texto": "O imóvel transcrito em nome de autarquia, embora objeto de promessa de venda a particulares, continua imune de impostos locais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "75", "texto": "Sendo vendedora uma autarquia, a sua imunidade fiscal não compreende o impôsto de transmissão inter vivos, que é encargo do comprador.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "76", "texto": "As sociedades de economia mista não estão protegidas pela imunidade fiscal do art. 31, V, a, Constituição Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "77", "texto": "Está isenta de impostos federais a aquisição de bens pela Rêde Ferroviária Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "78", "texto": "Estão isentas de impostos locais as emprêsas de energia elétrica, no que respeita às suas atividades específicas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "79", "texto": "O Banco do Brasil não tem isenção de tributos locais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "80", "texto": "Para a retomada de prédio situado fora do domicílio do locador exige-se a prova da necessidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "81", "texto": "As cooperativas não gozam de isenção de impostos locais, com fundamento na Constituição e nas leis federais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "82", "texto": "São inconstitucionais o impôsto de cessão e a taxa sôbre inscrição de promessa de venda de imóvel, substitutivos do impôsto de transmissão, por incidirem sôbre ato que não transfere o domínio.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "83", "texto": "Os ágios de importação incluem-se no valor dos artigos importados para incidência do impôsto de consumo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "84", "texto": "Não estão isentos do impôsto de consumo os produtos importados pelas cooperativas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "85", "texto": "Não estão sujeitos ao impôsto de consumo os bens de uso pessoal e doméstico trazidos, como bagagem, do exterior.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "86", "texto": "Não está sujeito ao impôsto de consumo automóvel usado, trazido do exterior pelo proprietário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "87", "texto": "Somente no que não colidirem com a Lei 3.244, de 14-8-1957, são aplicáveis acordos tarifários anteriores.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "88", "texto": "É válida a majoração da tarifa alfandegária, resultante da Lei 3.244, de 14-8-1957, que modificou o Acordo Geral sôbre Tarifas Aduaneiras e Comércio (GATT), aprovado pela Lei 313, de 30-7-1948.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "89", "texto": "Estão isentas do impôsto de importação frutas importadas da Argentina, do Chile, da Espanha e de Portugal, enquanto vigentes os respectivos acordos comerciais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "90", "texto": "É legítima a lei local que faça incidir o impôsto de indústrias e profissões com base no movimento econômico do contribuinte.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "91", "texto": "A incidência do impôsto único não isenta o comerciante de combustíveis do impôsto de indústrias e profissões.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "92", "texto": "É constitucional o art. 100, II, da Lei 4.563, de 20-2-1957, do Município de Recife, que faz variar o imposto de licença em função do aumento do capital do contribuinte.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "93", "texto": "Não está isenta do imposto de renda a atividade profissional do arquiteto.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "94", "texto": "É competente a autoridade alfandegária para o desconto, na fonte, do impôsto de renda correspondente às comissões dos despachantes aduaneiros.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "95", "texto": "Para cálculo do impôsto de lucro extraordinário, incluem-se no capital as reservas do ano-base, apuradas em balanço.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "96", "texto": "O impôsto de lucro imobiliário incide sôbre a venda de imóvel da meação do cônjuge sobrevivente, ainda que aberta a sucessão antes da vigência da Lei 3.470, de 28-11-1958.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "97", "texto": "É devida a alíquota anterior do impôsto de lucro imobiliário, quando a promessa de venda houver sido celebrada antes da vigência da lei que a tiver elevado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "98", "texto": "Sendo o imóvel alienado na vigência da Lei 3.470, de 28-11-1958, ainda que adquirido por herança, usucapião ou a título gratuito, é devido o impôsto de lucro imobiliário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "99", "texto": "Não é devido o impôsto de lucro imobiliário, quando a alienação de imóvel adquirido por herança, ou a título gratuito, tiver sido anterior à vigência da Lei 3.470, de 28-11-1958.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "100", "texto": "Não é devido o impôsto de lucro imobiliário, quando a alienação de imóvel, adquirido por usucapião, tiver sido anterior à vigência da Lei 3.470, de 28-11-1958.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "101", "texto": "O mandado de segurança não substitui a ação popular.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "102", "texto": "É devido o imposto federal do selo pela incorporação de reservas, em reavaliação de ativo, ainda que realizada antes da vigência da Lei 3.519, de 30-12-1958.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "103", "texto": "É devido o imposto federal do selo na simples reavaliação de ativo, realizada posteriormente à vigência da Lei 3.519, de 30-12-1958.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "104", "texto": "Não é devido o imposto federal do selo na simples reavaliação de ativo anterior à vigência da Lei 3.519, de 30-12-1958.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "105", "texto": "Salvo se tiver havido premeditação, o suicídio do segurado no período contratual de carência não exime o segurador do pagamento do seguro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "106", "texto": "É legítima a cobrança de selo sobre registro de automóveis, na conformidade da legislação estadual.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "107", "texto": "É inconstitucional o imposto de selo de 3%, \"ad valorem\", do Paraná, quanto aos produtos remetidos para fora do estado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "108", "texto": "É legítima a incidência do imposto de transmissão \"inter vivos\" sobre o valor do imóvel ao tempo da alienação e não da promessa, na conformidade da legislação local.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "109", "texto": "É devida a multa prevista no art. 15, § 6º, da Lei 1.300, de 28-12-1950, ainda que a desocupação do imóvel tenha resultado da notificação e não haja sido proposta ação de despejo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "110", "texto": "O imposto de transmissão \"inter vivos\" não incide sobre a construção, ou parte dela, realizada pelo adquirente, mas sobre o que tiver sido construído ao tempo da alienação do terreno.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "111", "texto": "É legítima a incidência do impôsto de transmissão inter vivos sôbre a restituição, ao antigo proprietário, de imóvel que deixou de servir à finalidade da sua desapropriação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "112", "texto": "O imposto de transmissão \"causa mortis\" é devido pela alíquota vigente ao tempo da abertura da sucessão.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "113", "texto": "O imposto de transmissão \"causa mortis\" é calculado sobre o valor dos bens na data da avaliação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "114", "texto": "O imposto de transmissão \"causa mortis\" não é exigível antes da homologação do cálculo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "115", "texto": "Sôbre os honorários do advogado contratado pelo inventariante, com a homologação do juiz, não incide o impôsto de transmissão causa mortis .", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "116", "texto": "Em desquite ou inventário, é legítima a cobrança do chamado imposto de reposição, quando houver desigualdade nos valores partilhados.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "117", "texto": "A lei estadual pode fazer variar a alíquota do imposto de vendas e consignações em razão da espécie do produto.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "118", "texto": "Estão sujeitas ao imposto de vendas e consignações as transações sobre minerais que ainda não estão compreendidos na legislação federal sobre o imposto único.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "119", "texto": "É devido o imposto de vendas e consignações sobre a venda de cafés ao Instituto Brasileiro do Café, embora o lote, originariamente, se destinasse à exportação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "120", "texto": "Parede de tijolos de vidro translúcido pode ser levantada a menos de metro e meio do prédio vizinho, não importando servidão sôbre êle.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "121", "texto": "É vedada a capitalização de juros, ainda que expressamente convencionada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "122", "texto": "O enfiteuta pode purgar a mora enquanto não decretado o comisso por sentença.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "123", "texto": "Sendo a locação regida pelo Decreto 24.150, de 20-4-1934, o locatário não tem direito à purgação da mora prevista na Lei 1.300, de 28-12-1950.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "124", "texto": "É inconstitucional o adicional do imposto de vendas e consignações cobrado pelo Estado do Espírito Santo sobre cafés da cota de expurgo entregues ao Instituo Brasileiro do Café.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "125", "texto": "Não é devido o impôsto de vendas e consignações sôbre a parcela do impôsto de consumo que onera a primeira venda realizada pelo produtor.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "126", "texto": "É inconstitucional a chamada taxa de aguardente, do Instituto do Açúcar e do Álcool.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "127", "texto": "É indevida a taxa de armazenagem, posteriormente aos primeiros trinta dias, quando não exigível o impôsto de consumo, cuja cobrança tenha motivado a retenção da mercadoria.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "128", "texto": "É indevida a taxa de assistência médica e hospitalar das instituições de previdência social.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "129", "texto": "Na conformidade da legislação local, é legítima a cobrança de taxa de calçamento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "130", "texto": "A taxa de despacho aduaneiro (art. 66 da Lei 3.244, de 14-8-1957) continua a ser exigível após o Decreto Legislativo 14, de 25-8-1960, que aprovou alterações introduzidas no Acordo Geral sobre Tarifas Aduaneiras e Comércio (GATT).", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "131", "texto": "A taxa de despacho aduaneiro (art. 66 da Lei 3.244, de 14-8-1957) continua a ser exigível após o Decreto Legislativo 14, de 25-8-1960, que aprovou alterações introduzidas no Acordo Geral sobre Tarifas Aduaneiras e Comércio (GATT).", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "132", "texto": "Não é devida a taxa de previdência social na importação de amianto bruto ou em fibra.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "133", "texto": "Não é devida a taxa de despacho aduaneiro na importação de fertilizantes e inseticidas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "134", "texto": "A isenção fiscal para a importação de frutas da Argentina compreende a taxa de despacho aduaneiro e a taxa de previdência social.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "135", "texto": "É inconstitucional a taxa de eletrificação de Pernambuco.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "136", "texto": "É constitucional a taxa de estatística da Bahia.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "137", "texto": "A taxa de fiscalização da exportação incide sobre a bonificação cambial concedida ao exportador.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "138", "texto": "É inconstitucional a taxa contra fogo, do Estado de Minas Gerais, incidente sobre prêmio de seguro contra fogo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "139", "texto": "É indevida a cobrança do imposto de transação a que se refere a Lei 899/1957, art. 58, IV, \"e\", do antigo Distrito Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "140", "texto": "Na importação de lubrificantes é devida a taxa de previdência social.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "141", "texto": "Não incide a taxa de previdência social sobre combustíveis.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "142", "texto": "Não é devida a taxa de previdência social sobre mercadorias isentas do imposto de importação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "143", "texto": "Na forma da lei estadual, é devido o imposto de vendas e consignações na exportação de café pelo Estado da Guanabara, embora proveniente de outro estado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "144", "texto": "É inconstitucional a incidência da taxa de recuperação econômica de Minas Gerais sobre contrato sujeito ao imposto federal do selo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "145", "texto": "Não há crime, quando a preparação do flagrante pela polícia torna impossível a sua consumação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "146", "texto": "A prescrição da ação penal regula-se pela pena concretizada na sentença, quando não há recurso da acusação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "147", "texto": "A prescrição de crime falimentar começa a correr da data em que deveria estar encerrada a falência, ou do trânsito em julgado da sentença que a encerrar ou que julgar cumprida a concordata.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "148", "texto": "É legítimo o aumento de tarifas portuárias por ato do Ministro da Viação e Obras Públicas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "149", "texto": "É imprescritível a ação de investigação de paternidade, mas não o é a de petição de herança.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "150", "texto": "Prescreve a execução no mesmo prazo de prescrição da ação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "151", "texto": "Prescreve em um ano a ação do segurador sub-rogado para haver indenização por extravio ou perda de carga transportada por navio.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "152", "texto": "A ação para anular venda de ascendente a descendente, sem consentimento dos demais, prescreve em quatro anos a contar da abertura da sucessão. (revogada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "153", "texto": "Simples protesto cambiário não interrompe a prescrição.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "154", "texto": "Simples vistoria não interrompe a prescrição.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "155", "texto": "É relativa a nulidade do processo criminal por falta de intimação da expedição de precatória para inquirição de testemunha.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "156", "texto": "É absoluta a nulidade do julgamento, pelo júri, por falta de quesito obrigatório.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "157", "texto": "É necessária prévia autorização do Presidente da República para desapropriação, pelos Estados, de empresa de energia elétrica.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "158", "texto": "Salvo estipulação contratual averbada no registro imobiliário, não responde o adquirente pelas benfeitorias do locatário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "159", "texto": "Cobrança excessiva, mas de boa-fé, não dá lugar às sanções do art. 1.531 do Código Civil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "160", "texto": "É nula a decisão do Tribunal que acolhe, contra o réu, nulidade não argüida no recurso da acusação, ressalvados os casos de recurso de ofício.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "161", "texto": "Em contrato de transporte, é inoperante a cláusula de não indenizar.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "162", "texto": "É absoluta a nulidade do julgamento pelo júri, quando os quesitos da defesa não precedem aos das circunstâncias agravantes.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "163", "texto": "Salvo contra a Fazenda Pública, sendo a obrigação ilíquida, contam-se os juros moratórios desde a citação inicial para a ação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "164", "texto": "No processo de desapropriação, são devidos juros compensatórios desde a antecipada imissão de posse, ordenada pelo juiz, por motivo de urgência.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "165", "texto": "A venda realizada diretamente pelo mandante ao mandatário não é atingida pela nulidade do art. 1.133, II, do Código Civil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "166", "texto": "É inadmissível o arrependimento no compromisso de compra e venda sujeito ao regime do Decreto-Lei 58, de 10-12-1937.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "167", "texto": "Não se aplica o regime do Decreto-Lei 58, de 10-12-1937, ao compromisso de compra e venda não inscrito no registro imobiliário, salvo se o promitente vendedor se obrigou a efetuar o registro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "168", "texto": "Para os efeitos do Decreto-Lei 58, de 10-12-1937, admite-se a inscrição imobiliária do compromisso de compra e venda no curso da ação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "169", "texto": "Depende de sentença a aplicação da pena de comisso.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "170", "texto": "É resgatável a enfiteuse instituída anteriormente à vigência do Código Civil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "171", "texto": "Não se admite, na locação em curso, de prazo determinado, a majoração de encargos a que se refere à Lei 3.844, de 15-12-1960.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "172", "texto": "Não se admite, na locação em curso, de prazo determinado, o reajustamento de aluguel a que se refere a Lei 3.085, de 29-12-1956.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "173", "texto": "Em caso de obstáculo judicial, admite-se a purga da mora, pelo locatário, além do prazo legal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "174", "texto": "Para a retomada do imóvel alugado, não é necessária a comprovação dos requisitos legais na notificação prévia.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "175", "texto": "Admite-se a retomada de imóvel alugado para uso de filho que vai contrair matrimônio.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "176", "texto": "O promitente comprador, nas condições previstas na Lei 1.300, de 28-12-1950, pode retomar o imóvel locado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "177", "texto": "O cessionário do promitente comprador, nas mesmas condições deste, pode retomar o imóvel locado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "178", "texto": "Não excederá de cinco anos a renovação judicial de contrato de locação, fundada no Decreto 24.150, de 20-4-1934.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "179", "texto": "O aluguel arbitrado judicialmente nos termos da Lei 3.085, de 29-12-1956, art. 6º, vigora a partir da data do laudo pericial.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "180", "texto": "Na ação revisional do art. 31 do Decreto 24.150, de 20-4-1934, o aluguel arbitrado vigora a partir do laudo pericial.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "181", "texto": "Na retomada, para construção mais útil de imóvel sujeito ao Decreto 24.150, de 20-4-1934, é sempre devida indenização para despesas de mudança do locatário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "182", "texto": "Não impede o reajustamento do débito pecuário, nos termos da Lei 1.002, de 24-12-1949, a falta de cancelamento da renúncia à moratória da Lei 209, de 2-1-1948.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "183", "texto": "Não se incluem no reajustamento pecuário dívidas estranhas à atividade agropecuária.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "184", "texto": "Não se incluem no reajustamento pecuário dívidas contraídas posteriormente a 19-12-1946.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "185", "texto": "Em processo de reajustamento pecuário, não responde a União pelos honorários do advogado do credor ou do devedor.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "186", "texto": "Não infringe a lei a tolerância da quebra de 1% no transporte por estrada de ferro, prevista no regulamento de transportes.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "187", "texto": "A responsabilidade contratual do transportador, pelo acidente com o passageiro, não é elidida por culpa de terceiro, contra o qual tem ação regressiva.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "188", "texto": "O segurador tem ação regressiva contra o causador do dano, pelo que efetivamente pagou, até ao limite previsto no contrato de seguro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "189", "texto": "Avais em branco e superpostos consideram-se simultâneos e não sucessivos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "190", "texto": "O não pagamento de título vencido há mais de trinta dias, sem protesto, não impede a concordata preventiva.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "191", "texto": "Inclui-se no crédito habilitado em falência a multa fiscal simplesmente moratória.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "192", "texto": "Não se inclui no crédito habilitado em falência a multa fiscal com efeito de pena administrativa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "193", "texto": "Para a restituição prevista no art. 76, § 2º, da Lei de Falências, conta-se o prazo de quinze dias da entrega da coisa e não da sua remessa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "194", "texto": "É competente o Ministro do Trabalho para a especificação das atividades insalubres.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "195", "texto": "Contrato de trabalho para obra certa, ou de prazo determinado, transforma-se em contrato de prazo indeterminado, quando prorrogado por mais de quatro anos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "196", "texto": "Ainda que exerça atividade rural, o empregado de empresa industrial ou comercial é classificado de acordo com a categoria do empregador.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "197", "texto": "O empregado com representação sindical só pode ser despedido mediante inquérito em que se apure falta grave.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "198", "texto": "As ausências motivadas por acidente do trabalho não são descontáveis do período aquisitivo das férias.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "199", "texto": "O salário das férias do empregado horista corresponde à média do período aquisitivo, não podendo ser inferior ao mínimo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "200", "texto": "Não é inconstitucional a Lei 1.530, de 26.12.1951, que manda incluir na indenização por despedida injusta parcela correspondente a férias proporcionais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "201", "texto": "O vendedor pracista, remunerado mediante comissão, não tem direito ao repouso semanal remunerado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "202", "texto": "Na equiparação de salário, em caso de trabalho igual, toma-se em conta o tempo de serviço na função, e não no emprego.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "203", "texto": "Não está sujeita à vacância de sessenta dias a vigência de novos níveis de salário-mínimo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "204", "texto": "Tem direito o trabalhador substituto, ou de reserva, ao salário mínimo no dia em que fica à disposição do empregador sem ser aproveitado na função específica; se aproveitado, recebe o salário contratual.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "205", "texto": "Tem direito a salário integral o menor não sujeito a aprendizagem metódica.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "206", "texto": "É nulo o julgamento ulterior pelo júri com a participação de jurado que funcionou em julgamento anterior do mesmo processo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "207", "texto": "As gratificações habituais, inclusive a de Natal, consideram-se tacitamente convencionadas, integrando o salário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "208", "texto": "O assistente do Ministério Público não pode recorrer, extraordinariamente, de decisão concessiva de habeas corpus.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "209", "texto": "O salário-produção, como outras modalidades de salário-prêmio, é devido, desde que verificada a condição a que estiver subordinado, e não pode ser suprimido unilateralmente, pelo empregador, quando pago com habitualidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "210", "texto": "O assistente do Ministério Público pode recorrer, inclusive extraordinariamente, na ação penal, nos casos dos arts. 584, § 1º, e 598 do Cód. de Proc. Penal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "211", "texto": "Contra a decisão proferida sobre o agravo no auto do processo, por ocasião do julgamento da apelação, não se admitem embargos infringentes ou de nulidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "212", "texto": "Tem direito ao adicional de serviço perigoso o empregado de posto de revenda de combustível líquido.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "213", "texto": "É devido o adicional de serviço noturno, ainda que sujeito o empregado ao regime de revezamento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "214", "texto": "A duração legal da hora de serviço noturno (52 minutos e 30 segundos) constitui vantagem suplementar que não dispensa o salário adicional.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "215", "texto": "Conta-se a favor do empregado readmitido o tempo de serviço anterior, salvo se houver sido despedido por falta grave ou tiver recebido a indenização legal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "216", "texto": "Para decretação da absolvição de instância pela paralisação do processo por mais de trinta dias, é necessário que o autor, previamente intimado, não promova o andamento da causa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "217", "texto": "Tem direito de retornar ao emprego, ou ser indenizado em caso de recusa do empregador, o aposentado que recupera a capacidade de trabalho dentro de cinco anos, a contar da aposentadoria, que se torna definitiva após esse prazo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "218", "texto": "É competente o juízo da Fazenda Nacional da capital do Estado, e não o da situação da coisa, para a desapropriação promovida por empresa de energia elétrica, se a União Federal intervém como assistente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "219", "texto": "Para a indenização devida a empregado que tinha direito a ser readmitido, e não foi, levam-se em conta as vantagens advindas à sua categoria no período do afastamento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "220", "texto": "A indenização devida a empregado estável, que não é readmitido, ao cessar sua aposentadoria, deve ser paga em dobro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "221", "texto": "A transferência de estabelecimento, ou a sua extinção parcial, por motivo que não seja de força maior, não justifica a transferência de empregado estável.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "222", "texto": "O princípio da identidade física do juiz não é aplicável às juntas de conciliação e julgamento da justiça do trabalho.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "223", "texto": "Concedida isenção de custas ao empregado, por elas não responde o sindicato que o representa em juízo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "224", "texto": "Os juros da mora, nas reclamações trabalhistas, são contados desde a notificação inicial.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "225", "texto": "Não é absoluto o valor probatório das anotações da carteira profissional.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "226", "texto": "Na ação de desquite, os alimentos são devidos desde a inicial e não da data da decisão que os concede.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "227", "texto": "A concordata do empregador não impede a execução de crédito nem a reclamação de empregado na Justiça do Trabalho.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "228", "texto": "Não é provisória a execução na pendência de recurso extraordinário, ou de agravo destinado a fazê-lo admitir.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "229", "texto": "A indenização acidentária não exclui a do direito comum, em caso de dolo ou culpa grave do empregador.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "230", "texto": "A prescrição da ação de acidente do trabalho conta-se do exame pericial que comprovar a enfermidade ou verificar a natureza da incapacidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "231", "texto": "O revel, em processo cível, pode produzir provas, desde que compareça em tempo oportuno.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "232", "texto": "Em caso de acidente do trabalho, são devidas diárias até doze meses, as quais não se confundem com a indenização acidentária nem com o auxílio-enfermidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "233", "texto": "Salvo em caso de divergência qualificada (Lei 623/1949), não cabe recurso de embargos contra decisão que nega provimento a agravo ou não conhece de recurso extraordinário, ainda que por maioria de votos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "234", "texto": "São devidos honorários de advogado em ação de acidente do trabalho julgada procedente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "235", "texto": "É competente para a ação de acidente de trabalho a Justiça Cível comum, inclusive em segunda instância, ainda que seja parte autarquia seguradora.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "236", "texto": "Em ação de acidente do trabalho, a autarquia seguradora não tem isenção de custas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "237", "texto": "O usucapião pode ser argüido em defesa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "238", "texto": "Em caso de acidente do trabalho, a multa pelo retardamento da liquidação é exigível do segurador sub-rogado, ainda que autarquia.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "239", "texto": "Decisão que declara indevida a cobrança do imposto em determinado exercício não faz coisa julgada em relação aos posteriores.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "240", "texto": "O depósito para recorrer, em ação de acidente do trabalho, é exigível do segurador sub-rogado, ainda que autarquia.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "241", "texto": "A contribuição previdenciária incide sobre o abono incorporado ao salário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "242", "texto": "O agravo no auto do processo deve ser apreciado, no julgamento da apelação, ainda que o agravante não tenha apelado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "243", "texto": "Em caso de dupla aposentadoria, os proventos a cargo do IAPFESP não são equiparáveis aos pagos pelo Tesouro Nacional, mas calculados à base da média salarial nos últimos doze meses de serviço.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "244", "texto": "A importação de máquinas de costura está isenta do imposto de consumo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "245", "texto": "A imunidade parlamentar não se estende ao co-réu sem essa prerrogativa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "246", "texto": "Comprovado não ter havido fraude, não se configura o crime de emissão de cheque sem fundos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "247", "texto": "O relator não admitirá os embargos da Lei 623, de 19-2-1949, nem deles conhecerá o Supremo Tribunal Federal, quando houver jurisprudência firme do Plenário no mesmo sentido da decisão embargada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "248", "texto": "É competente, originariamente, o Supremo Tribunal Federal, para mandado de segurança contra ato do Tribunal de Contas da União.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "249", "texto": "É competente o Supremo Tribunal Federal para a ação rescisória, quando, embora não tendo conhecido do recurso extraordinário, ou havendo negado provimento ao agravo, tiver apreciado a questão federal controvertida.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "250", "texto": "A intervenção da União desloca o processo do Juízo Cível comum para o Fazendário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "251", "texto": "Responde a Rede Ferroviária Federal S.A. perante o foro comum e não perante o juízo especial da Fazenda Nacional, a menos que a União intervenha na causa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "252", "texto": "Na ação rescisória, não estão impedidos juízes que participaram do julgamento rescindendo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "253", "texto": "Nos embargos da Lei 623, de 19-2-1949, no Supremo Tribunal Federal, a divergência somente será acolhida, se tiver sido indicada na petição de recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "254", "texto": "Incluem-se os juros moratórios na liquidação, embora omisso o pedido inicial ou a condenação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "255", "texto": "Sendo ilíquida a obrigação, os juros moratórios, contra a Fazenda Pública, incluídas as autarquias, são contados do trânsito em julgado da sentença de liquidação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "256", "texto": "É dispensável pedido expresso para condenação do réu em honorários, com fundamento nos arts. 63 ou 64 do Código de Processo Civil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "257", "texto": "São cabíveis honorários de advogado na ação regressiva do segurador contra o causador do dano.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "258", "texto": "É admissível reconvenção em ação declaratória.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "259", "texto": "Para produzir efeito em juízo não é necessária a inscrição, no Registro Público, de documentos de procedência estrangeira, autenticados por via consular.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "260", "texto": "O exame de livros comerciais, em ação judicial, fica limitado às transações entre os litigantes.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "261", "texto": "Para a ação de indenização, em caso de avaria, é dispensável que a vistoria se faça judicialmente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "262", "texto": "Não cabe medida possessória liminar para liberação alfandegária de automóvel.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "263", "texto": "O possuidor deve ser citado pessoalmente para a ação de usucapião.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "264", "texto": "Verifica-se a prescrição intercorrente pela paralisação da ação rescisória por mais de cinco anos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "265", "texto": "Na apuração de haveres não prevalece o balanço não aprovado pelo sócio falecido, excluído ou que se retirou.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "266", "texto": "Não cabe mandado de segurança contra lei em tese.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "267", "texto": "Não cabe mandado de segurança contra ato judicial passível de recurso ou correição.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "268", "texto": "Não cabe mandado de segurança contra decisão judicial com trânsito em julgado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "269", "texto": "O mandado de segurança não é substitutivo de ação de cobrança.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "270", "texto": "Não cabe mandado de segurança para impugnar enquadramento da Lei 3.780, de 12-7-1960, que envolva exame de prova ou de situação funcional complexa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "271", "texto": "Concessão de mandado de segurança não produz efeitos patrimoniais em relação a período pretérito, os quais devem ser reclamados administrativamente ou pela via judicial própria.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "272", "texto": "Não se admite como ordinário recurso extraordinário de decisão denegatória de mandado de segurança.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "273", "texto": "Nos embargos da Lei 623, de 19-2-1949, a divergência sôbre questão prejudicial ou preliminar, suscitada após a interposição do recurso extraordinário, ou do agravo, somente será acolhida se o acórdão-padrão fôr anterior à decisão embargada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "274", "texto": "É inconstitucional a taxa de serviço contra fogo cobrada pelo Estado de Pernambuco. (revogada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "275", "texto": "Está sujeita a recurso ex officio sentença concessiva de reajustamento pecuário anterior à vigência da Lei 2.804, de 25-6-1956.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "276", "texto": "Não cabe recurso de revista em ação executiva fiscal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "277", "texto": "São cabíveis embargos, em favor da Fazenda Pública, em ação executiva fiscal, não sendo unânime a decisão.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "278", "texto": "São cabíveis embargos em ação executiva fiscal contra decisão reformatória da de primeira instância, ainda que unânime.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "279", "texto": "Para simples reexame de prova não cabe recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "280", "texto": "Por ofensa a direito local não cabe recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "281", "texto": "É inadmissível o recurso extraordinário, quando couber na justiça de origem, recurso ordinário da decisão impugnada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "282", "texto": "É inadmissível o recurso extraordinário, quando não ventilada, na decisão recorrida, a questão federal suscitada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "283", "texto": "É inadmissível o recurso extraordinário, quando a decisão recorrida assenta em mais de um fundamento suficiente e o recurso não abrange todos eles.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "284", "texto": "É inadmissível o recurso extraordinário, quando a deficiência na sua fundamentação não permitir a exata compreensão da controvérsia.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "285", "texto": "Não sendo razoável a argüição de inconstitucionalidade, não se conhece do recurso extraordinário fundado na letra \"c\" do art. 101, III, da Constituição Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "286", "texto": "Não se conhece do recurso extraordinário fundado em divergência jurisprudencial, quando a orientação do plenário do Supremo Tribunal Federal já se firmou no mesmo sentido da decisão recorrida.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "287", "texto": "Nega-se provimento ao agravo, quando a deficiência na sua fundamentação, ou na do recurso extraordinário, não permitir a exata compreensão da controvérsia.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "288", "texto": "Nega-se provimento a agravo para subida de recurso extraordinário, quando faltar no traslado o despacho agravado, a decisão recorrida, a petição de recurso extraordinário ou qualquer peça essencial à compreensão da controvérsia. Jurisprudência selecionada ● Princípio tempus regit actum : aplicação do verbete aos agravos protocolados antes do advento da Lei 12.322/2010 Agravo regimental no agravo de instrumento. Matéria criminal. Ausência de peça essencial. Inaplicabilidade da Lei 12.322/2010 . Agravo de instrumento protocolado em data anterior à vigência da legislação em questão. Incidência do princípio tempus regit actum. Precedentes. 1. A petição de interposição do recurso extraordinário e as respectivas contrarrazões ou prova da sua inexistência, são peças de traslado obrigatório, nos termos do art. 544, § 1º, do Código de Processo Civil. Incidência da Súmula 288/STF . 2. É firme a jurisprudência do Supremo Tribunal Federal de que incumbe exclusivamente ao agravante a responsabilidade pela correta formação do instrumento, com o completo traslado das peças, não se admitindo o suprimento de eventuais falhas ou a realização de diligências junto à Suprema Corte. 3. Não se mostra aplicável a inovadora sistemática da Lei 12.322/2010 , pois o agravo de instrumento foi protocolado em data anterior - 16/4/08 - à vigência da legislação em questão, que, por sua vez, não traz previsão expressa que possibilite a retroação dos seus efeitos. Portanto, inegável, na espécie, a incidência do princípio tempus regit actum. 4. Agravo regimental não provido. [ AI 858.916 AgR , rel. min. Dias Toffoli , 1ª T, j. 18-6-2013, DJE 150 de 5-8-2013.] Penal. Agravo regimental em agravo de instrumento. Peças obrigatórias. Ausência. Dever da parte de zelar pela correta formação do instrumento. Súmula 288 . Incidência. Lei 12.322/2010 . Irretroatividade. Agravo provido. I - O agravo de instrumento deve ser instruído com as peças obrigatórias e também com as necessárias ao exato conhecimento das questões discutidas. II - É dever processual da parte zelar pela correta formação do instrumento. Precedentes. III - Nos termos do art. 2º do Código de Processo Penal , a lei adjetiva penal tem eficácia imediata, preservando-se os atos praticados anteriormente à sua vigência, isso porque vigora, no processo penal, o princípio \"tempus regit actum\" s egundo o qual são plenamente válidos os atos processuais praticados sob a vigência de lei anterior, uma vez que as normas processuais penais não possuem efeito retroativo. IV - A Lei 12.322/2010 , que dispôs sobre a nova sistemática do agravo contra decisão que não admite recurso extraordinário ou especial, entrou em vigor 90 dias após a sua publicação, no dia 09/12/2010. Lei cuja aplicação não pode ocorrer de forma retroativa. Precedentes. V - Agravo regimental desprovido. [ AI 853.545 AgR , rel. min. Ricardo Lewandowski , 2ª T, j. 26-2-2013, DJE 46 de 11-3-2013.] Observação Para informações adicionais, clique aqui . Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui . Mapa do Site Acessibilidade Praça dos Três Poderes, Brasília - DF - CEP 70175-900", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "289", "texto": "O provimento do agravo por uma das turmas do Supremo Tribunal Federal ainda que sem ressalva, não prejudica a questão do cabimento do recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "290", "texto": "Nos embargos da Lei 623, de 19.2.1949, a prova de divergência far-se-á por certidão, ou mediante indicação do \"Diário da Justiça\" ou de repertório de jurisprudência autorizado, que a tenha publicado, com a transcrição do trecho que configure a divergência, mencionadas as circunstâncias que identifiquem ou assemelhem os casos confrontados.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "291", "texto": "No recurso extraordinário pela letra \"d\" do art. 101, número III, da Constituição , a prova do dissídio jurisprudencial far-se-á por certidão, ou mediante indicação do \"Diário da Justiça\" ou de repertório de jurisprudência autorizado, com a transcrição do trecho que configure a divergência, mencionadas as circunstâncias que identifiquem ou assemelhem os casos confrontados.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "292", "texto": "Interposto o recurso extraordinário por mais de um dos fundamentos indicados no art. 101, III da Constituição , a admissão apenas por um deles não prejudica o seu conhecimento por qualquer dos outros.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "293", "texto": "São inadmissíveis embargos infringentes contra decisão em matéria constitucional submetida ao plenário dos tribunais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "294", "texto": "São inadmissíveis embargos infringentes contra decisão do Supremo Tribunal Federal em mandado de segurança.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "295", "texto": "São inadmissíveis embargos infringentes contra decisão unânime do Supremo Tribunal Federal em ação rescisória.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "296", "texto": "São inadmissíveis embargos infringentes sobre matéria não ventilada, pela Turma, no julgamento do recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "297", "texto": "Oficiais e praças das milícias dos Estados, no exercício de função policial civil, não são considerados militares para efeitos penais, sendo competente a Justiça Comum para julgar os crimes cometidos por ou contra eles.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "298", "texto": "O legislador ordinário só pode sujeitar civis à justiça militar, em tempo de paz, nos crimes contra a segurança externa do país ou as instituições militares.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "299", "texto": "O recurso ordinário e o extraordinário interpostos no mesmo processo de mandado de segurança, ou de habeas corpus , serão julgados conjuntamente pelo Tribunal Pleno.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "300", "texto": "São incabíveis os embargos da Lei 623, de 19-2-1949, contra provimento de agravo para subida de recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "301", "texto": "Por crime de responsabilidade, o procedimento penal contra prefeito municipal fica condicionado ao seu afastamento do cargo por \" impeachment \", ou à cessação do exercício por outro motivo. (cancelada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "302", "texto": "Está isenta da taxa de previdência social a importação de petróleo bruto.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "303", "texto": "Não é devido o impôsto federal de sêlo em contrato firmado com autarquia anteriormente à vigência da Emenda Constitucional 5, de 21-11-1961.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "304", "texto": "Decisão denegatória de mandado de segurança, não fazendo coisa julgada contra o impetrante, não impede o uso da ação própria.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "305", "texto": "Acordo de desquite ratificado por ambos os cônjuges não é retratável unilateralmente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "306", "texto": "As taxas de recuperação econômica e de assistência hospitalar de Minas Gerais são legítimas, quando incidem sôbre matéria tributável pelo Estado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "307", "texto": "É devido o adicional de serviço insalubre, calculado à base do salário mínimo da região, ainda que a remuneração contratual seja superior ao salário mínimo acrescido da taxa de insalubridade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "308", "texto": "A taxa de despacho aduaneiro, sendo adicional do impôsto de importação, não incide sôbre borracha importada com isenção daquele impôsto.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "309", "texto": "A taxa de despacho aduaneiro, sendo adicional do impôsto de importação, não está compreendida na isenção do impôsto de consumo para automóvel usado trazido do exterior pelo proprietário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "310", "texto": "Quando a intimação tiver lugar na sexta-feira, ou a publicação com efeito de intimação for feita nesse dia, o prazo judicial terá início na segunda-feira imediata, salvo se não houver expediente, caso em que começará no primeiro dia útil que se seguir.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "311", "texto": "No típico acidente do trabalho, a existência de ação judicial não exclui a multa pelo retardamento da liquidação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "312", "texto": "Músico integrante de orquestra da emprêsa, com atuação permanente e vínculo de subordinação, está sujeito a legislação geral do trabalho, e não à especial dos artistas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "313", "texto": "Provada a identidade entre o trabalho diurno e o noturno, é devido o adicional, quanto a este, sem a limitação do art. 73, § 3º, da C.L.T., independentemente da natureza da atividade do empregador.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "314", "texto": "Na composição do dano por acidente do trabalho, ou de transporte, não é contrário à lei tomar para base da indenização o salário do tempo da perícia ou da sentença.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "316", "texto": "A simples adesão à greve não constitui falta grave.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "317", "texto": "São improcedentes os embargos declaratórios, quando não pedida a declaração do julgado anterior, em que se verificou a omissão.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "318", "texto": "É legítima a cobrança, em 1962, pela municipalidade de São Paulo, do impôsto de indústrias e profissões, consoante as leis 5.917 e 5.919, de 1961 (aumento anterior à vigência do orçamento e incidência do tributo sôbre o movimento econômico do contribuinte).", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "319", "texto": "O prazo do recurso ordinário para o Supremo Tribunal Federal, em habeas corpus ou mandado de segurança, é de cinco dias.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "320", "texto": "A apelação despachada pelo juiz no prazo legal não fica prejudicada pela demora da juntada, por culpa do cartório.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "321", "texto": "A Constituição Estadual pode estabelecer a irredutibilidade dos vencimentos do Ministério Público.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "322", "texto": "Não terá seguimento pedido ou recurso dirigido ao Supremo Tribunal Federal, quando manifestamente incabível, ou apresentado fora do prazo, ou quando for evidente a incompetência do Tribunal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "323", "texto": "É inadmissível a apreensão de mercadorias como meio coercitivo para pagamento de tributos", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "324", "texto": "A imunidade do art. 31, V, da Constituição Federal não compreende as taxas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "325", "texto": "Não foram encontrados precedentes que aplicassem a referida Súmula.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "327", "texto": "O Direito Trabalhista admite a prescrição intercorrente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "328", "texto": "É legítima a incidência do impôsto de transmissão inter vivos sôbre a doação de imóvel.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "330", "texto": "O Supremo Tribunal Federal não é competente para conhecer de mandado de segurança contra atos dos tribunais de justiça dos Estados.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "331", "texto": "É legítima a incidência do impôsto de transmissão causa mortis no inventário por morte presumida.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "332", "texto": "É legítima a incidência do impôsto de vendas e consignações sôbre a parcela do preço correspondente aos ágios cambiais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "333", "texto": "Está sujeita ao impôsto de vendas e consignações a venda realizada por invernista não qualificado como pequeno produtor.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "334", "texto": "É legítima a cobrança, ao empreiteiro, do impôsto de vendas e consignações, sôbre o valor dos materiais empregados, quando a empreitada não for apenas de lavor.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "335", "texto": "É válida a cláusula de eleição do fôro para os processos oriundos do contrato.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "336", "texto": "A imunidade da autarquia financiadora, quanto ao contrato de financiamento, não se estende à compra e venda entre particulares, embora constantes os dois atos de um só instrumento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "337", "texto": "A controvérsia entre o empregador e o segurador não suspende o pagamento devido ao empregado por acidente do trabalho.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "338", "texto": "Não cabe ação rescisória no âmbito da Justiça do Trabalho.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "339", "texto": "Não cabe ao Poder Judiciário, que não tem função legislativa, aumentar vencimentos de servidores públicos sob fundamento de isonomia.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "340", "texto": "Desde a vigência do Código Civil, os bens dominicais, como os demais bens públicos, não podem ser adquiridos por usucapião.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "341", "texto": "É presumida a culpa do patrão ou comitente pelo ato culposo do empregado ou preposto.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "342", "texto": "Não foram encontrados precedentes que aplicassem a referida súmula.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "343", "texto": "Não cabe ação rescisória por ofensa a literal disposição de lei, quando a decisão rescindenda se tiver baseado em texto legal de interpretação controvertida nos tribunais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "344", "texto": "Sentença de primeira instância concessiva de habeas corpus , em caso de crime praticado em detrimento de bens, serviços ou interesses da União, está sujeita a recurso ex officio.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "345", "texto": "Na chamada desapropriação indireta, os juros compensatórios são devidos a partir da perícia, desde que tenha atribuído valor atual ao imóvel.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "346", "texto": "A Administração Pública pode declarar a nulidade dos seus próprios atos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "347", "texto": "O Tribunal de Contas, no exercício de suas atribuições, pode apreciar a constitucionalidade das leis e dos atos do Poder Público.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "348", "texto": "É constitucional a criação de taxa de construção, conservação e melhoramento de estradas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "351", "texto": "É nula a citação por edital de réu preso na mesma unidade da federação em que o juiz exerce a sua jurisdição.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "352", "texto": "Não é nulo o processo penal por falta de nomeação de curador ao réu menor que teve a assistência de defensor dativo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "353", "texto": "São incabíveis os embargos da Lei 623, de 19-2-1949, com fundamento em divergência entre decisões da mesma Turma do Supremo Tribunal Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "354", "texto": "Em caso de embargos infringentes parciais, é definitiva a parte da decisão embargada em que não houve divergência na votação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "355", "texto": "Em caso de embargos infringentes parciais, é tardio o recurso extraordinário interposto após o julgamento dos embargos, quanto à parte da decisão embargada que não fora por eles abrangida.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "356", "texto": "O ponto omisso da decisão, sobre o qual não foram opostos embargos declaratórios, não pode ser objeto de recurso extraordinário, por faltar o requisito do prequestionamento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "357", "texto": "É lícita a convenção pela qual o locador renuncia, durante a vigência do contrato, à ação revisional do art. 31 do Decreto 24.150, de 20-4-1934.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "358", "texto": "O servidor público em disponibilidade tem direito aos vencimentos integrais do cargo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "359", "texto": "Ressalvada a revisão prevista em lei, os proventos da inatividade regulam-se pela lei vigente ao tempo em que o militar, ou o servidor civil, reuniu os requisitos necessários. (alterada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "360", "texto": "Não há prazo de decadência para a representação de inconstitucionalidade prevista no art. 8º, parágrafo único, da Constituição Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "361", "texto": "No processo penal, é nulo o exame realizado por um só perito, considerando-se impedido o que tiver funcionado, anteriormente, na diligência de apreensão.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "362", "texto": "A condição de ter o clube sede própria para a prática de jôgo lícito não o obriga a ser proprietário do imóvel em que tem sede.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "363", "texto": "A pessoa jurídica de direito privado pode ser demandada no domicílio da agência, ou estabelecimento, em que se praticou o ato.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "364", "texto": "Enquanto o Estado da Guanabara não tiver Tribunal Militar de segunda instância, o Tribunal de Justiça é competente para julgar os recursos das decisões da auditoria da Polícia Militar.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "365", "texto": "Pessoa jurídica não tem legitimidade para propor ação popular.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "366", "texto": "Não é nula a citação por edital que indica o dispositivo da lei penal, embora não transcreva a denúncia ou queixa, ou não resuma os fatos em que se baseia.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "367", "texto": "Concede-se liberdade ao extraditando que não for retirado do país no prazo do art. 16 do Decreto-Lei 394, de 28-4-1938.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "368", "texto": "Não há embargos infringentes no processo de reclamação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "369", "texto": "Julgados do mesmo tribunal não servem para fundamentar o recurso extraordinário por divergência jurisprudencial.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "370", "texto": "Julgada improcedente a ação renovatória de locação, terá o locatário, para desocupar o imóvel, o prazo de seis meses, acrescido de tantos meses quantos forem os anos da ocupação, até o limite total de dezoito meses.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "371", "texto": "Ferroviário, que foi admitido como servidor autárquico, não tem direito a dupla aposentadoria.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "372", "texto": "A Lei 2.752, de 10-4-1956, sobre dupla aposentadoria, aproveita, quando couber, a servidores aposentados antes de sua publicação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "374", "texto": "Na retomada para construção mais útil, não é necessário que a obra tenha sido ordenada pela autoridade pública.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "375", "texto": "Não renovada a locação regida pelo Decreto 24.150, de 20-4-1934, aplica-se o direito comum e não a legislação especial do inquilinato.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "376", "texto": "Na renovação de locação, regida pelo Decreto 24.150, de 20-4-1934, o prazo do nôvo contrato conta-se da transcrição da decisão exequenda no Registro de Títulos e Documentos; começa, porém, da terminação do contrato anterior, se esta tiver ocorrido antes do registro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "378", "texto": "Na indenização por desapropriação incluem-se honorários do advogado do expropriado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "379", "texto": "No acôrdo de desquite não se admite renúncia aos alimentos, que poderão ser pleiteados ulteriormente, verificados os pressupostos legais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "380", "texto": "Comprovada a existência de sociedade de fato entre os concubinos, é cabível a sua dissolução judicial, com a partilha do patrimônio adquirido pelo esforço comum.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "381", "texto": "Não se homologa sentença de divórcio obtida, por procuração, em país de que os cônjuges não eram nacionais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "382", "texto": "A vida em comum sob o mesmo teto, more uxorio , não é indispensável à caracterização do concubinato.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "383", "texto": "A prescrição em favor da Fazenda Pública recomeça a correr, por dois anos e meio, a partir do ato interruptivo, mas não fica reduzida aquém de cinco anos, embora o titular do direito a interrompa durante a primeira metade do prazo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "384", "texto": "A demissão de extranumerário do serviço público federal, equiparado a funcionário de provimento efetivo para efeito de estabilidade, é da competência do Presidente da República.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "385", "texto": "Oficial das Fôrças Armadas só pode ser reformado, em tempo de paz, por decisão de tribunal militar permanente, ressalvada a situação especial dos atingidos pelo art. 177 da Constituição de 1937.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "386", "texto": "Pela execução de obra musical por artistas remunerados é devido direito autoral, não exigível quando a orquestra fôr de amadores.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "387", "texto": "A cambial emitida ou aceita com omissões, ou em branco, pode ser completada pelo credor de boa-fé antes da cobrança ou do protesto.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "388", "texto": "O casamento da ofendida com quem não seja o ofensor faz cessar a qualidade do seu representante legal, e a ação penal só pode prosseguir por iniciativa da própria ofendida, observados os prazos legais de decadência e perempção. ( revogada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "389", "texto": "Salvo limite legal, a fixação de honorários de advogado, em complemento da condenação, depende das circunstâncias da causa, não dando lugar a recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "390", "texto": "A exibição judicial de livros comerciais pode ser requerida como medida preventiva.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "391", "texto": "O confinante certo deve ser citado, pessoalmente, para a ação de usucapião.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "392", "texto": "O prazo para recorrer de acórdão concessivo de segurança conta-se da publicação oficial de suas conclusões, e não da anterior ciência à autoridade para cumprimento da decisão.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "393", "texto": "Para requerer revisão criminal, o condenado não é obrigado a recolher-se à prisão.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "394", "texto": "Cometido o crime durante o exercício funcional, prevalece a competência especial por prerrogativa de função, ainda que o inquérito ou a ação penal sejam iniciados após a cessação daquele exercício. (cancelada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "395", "texto": "Não se conhece de recurso de habeas corpus cujo objeto seja resolver sobre o ônus das custas, por não estar mais em causa a liberdade de locomoção.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "396", "texto": "Para a ação penal por ofensa à honra, sendo admissível a exceção da verdade quanto ao desempenho de função pública, prevalece a competência especial por prerrogativa de função, ainda que já tenha cessado o exercício funcional do ofendido.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "397", "texto": "O poder de polícia da Câmara dos Deputados e do Senado Federal, em caso de crime cometido nas suas dependências, compreende, consoante o regimento, a prisão em flagrante do acusado e a realização do inquérito.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "398", "texto": "O Supremo Tribunal Federal não é competente para processar e julgar, originariamente, deputado ou senador acusado de crime.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "399", "texto": "Não cabe recurso extraordinário, por violação de lei federal, quando a ofensa alegada for a regimento de tribunal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "400", "texto": "Decisão que deu razoável interpretação à lei, ainda que não seja a melhor, não autoriza recurso extraordinário pela letra \"a\" do art. 101, III, da Constituição Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "401", "texto": "Não se conhece do recurso de revista, nem dos embargos de divergência, do processo trabalhista, quando houver jurisprudência firme do Tribunal Superior do Trabalho no mesmo sentido da decisão impugnada, salvo se houver colisão com a jurisprudência do Supremo Tribunal Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "402", "texto": "Vigia noturno tem direito a salário adicional.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "403", "texto": "É de decadência o prazo de trinta dias para instauração do inquérito judicial, a contar da suspensão, por falta grave, de empregado estável.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "404", "texto": "Não contrariam a Constituição os arts. 3º, 22 e 27 da Lei 3.244, de 14-8-1957, que definem as atribuições do Conselho de Política Aduaneira quanto à tarifa flexível.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "405", "texto": "Denegado o mandado de segurança pela sentença, ou no julgamento do agravo dela interposto, fica sem efeito a liminar concedida, retroagindo os efeitos da decisão contrária.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "406", "texto": "O estudante ou professor bolsista e o servidor público em missão de estudo satisfazem a condição da mudança de residência para o efeito de trazer automóvel do exterior, atendidos os demais requisitos legais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "407", "texto": "Não tem direito ao têrço de campanha o militar que não participou de operações de guerra, embora servisse na \"zona de guerra\".", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "408", "texto": "Os servidores fazendários não têm direito a percentagem pela arrecadação de receita federal destinada ao Banco Nacional de Desenvolvimento Econômico.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "409", "texto": "Ao retomante, que tenha mais de um prédio alugado, cabe optar entre eles, salvo abuso de direito.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "410", "texto": "Se o locador, utilizando prédio próprio para residência ou atividade comercial, pede o imóvel locado para uso próprio, diverso do que tem o por ele ocupado, não está obrigado a provar a necessidade, que se presume.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "411", "texto": "O locatário autorizado a ceder a locação pode sublocar o imóvel.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "413", "texto": "O compromisso de compra e venda de imóveis, ainda que não loteados, dá direito à execução compulsória, quando reunidos os requisitos legais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "414", "texto": "Não se distingue a visão direta da oblíqua na proibição de abrir janela, ou fazer terraço, eirado, ou varanda, a menos de metro e meio do prédio de outrem.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "415", "texto": "Servidão de trânsito não titulada, mas tornada permanente, sobretudo pela natureza das obras realizadas, considera-se aparente, conferindo direito à proteção possessória.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "416", "texto": "Pela demora no pagamento do preço da desapropriação não cabe indenização complementar além dos juros.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "417", "texto": "Pode ser objeto de restituição, na falência, dinheiro em poder do falido, recebido em nome de outrem, ou do qual, por lei ou contrato, não tivesse êle a disponibilidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "418", "texto": "O empréstimo compulsório não é tributo, e sua arrecadação não está sujeita à exigência constitucional da prévia autorização orçamentária.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "419", "texto": "Os municípios têm competência para regular o horário do comércio local, desde que não infrinjam leis estaduais ou federais válidas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "420", "texto": "Não se homologa sentença proferida no estrangeiro sem prova do trânsito em julgado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "421", "texto": "Não impede a extradição a circunstância de ser o extraditando casado com brasileira ou ter filho brasileiro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "422", "texto": "A absolvição criminal não prejudica a medida de segurança, quando couber, ainda que importe privação da liberdade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "423", "texto": "Não transita em julgado a sentença por haver omitido o recurso ex officio , que se considera interposto ex lege .", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "424", "texto": "Transita em julgado o despacho saneador de que não houve recurso, excluídas as questões deixadas, explícita ou implicitamente, para a sentença.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "425", "texto": "O agravo despachado no prazo legal não fica prejudicado pela demora da juntada, por culpa do cartório; nem o agravo entregue em cartório no prazo legal, embora despachado tardiamente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "426", "texto": "A falta do termo específico não prejudica o agravo no auto do processo, quando oportuna a interposição por petição ou no têrmo da audiência.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "427", "texto": "A falta de petição de interposição não prejudica o agravo no auto do processo tomado por termo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "428", "texto": "Não fica prejudicada a apelação entregue em cartório no prazo legal, embora despachada tardiamente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "429", "texto": "A existência de recurso administrativo com efeito suspensivo não impede o uso do mandado de segurança contra omissão da autoridade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "430", "texto": "Pedido de reconsideração na via administrativa não interrompe o prazo para o mandado de segurança.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "431", "texto": "É nulo o julgamento de recurso criminal, na segunda instância, sem prévia intimação, ou publicação da pauta, salvo em habeas corpus .", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "432", "texto": "Não cabe recurso extraordinário com fundamento no art. 101, III, \" d \", da Constituição Federal, quando a divergência alegada for entre decisões da Justiça do Trabalho.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "433", "texto": "É competente o Tribunal Regional do Trabalho para julgar mandado de segurança contra ato de seu presidente em execução de sentença trabalhista.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "434", "texto": "A controvérsia entre seguradores indicados pelo empregador na ação de acidente do trabalho não suspende o pagamento devido ao acidentado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "435", "texto": "O impôsto de transmissão causa mortis pela transferência de ações é devido ao Estado em que tem sede a companhia.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "436", "texto": "É válida a Lei 4.093, de 24-10-1959, do Paraná, que revogou a isenção concedida às cooperativas por lei anterior.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "437", "texto": "Está isenta da taxa de despacho aduaneiro a importação de equipamento para a indústria automobilística, segundo plano aprovado, no prazo legal, pelo órgão competente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "438", "texto": "É ilegítima a cobrança, em 1962, da Taxa de Educação e Saúde, de Santa Catarina, adicional do impôsto de vendas e consignações. Jurisprudência selecionada A pesquisa no banco de jurisprudência do STF não recuperou decisões com menção a este enunciado após a Constituição Federal de 1988.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "439", "texto": "Estão sujeitos à fiscalização tributária ou previdenciária quaisquer livros comerciais, limitado o exame aos pontos objeto da investigação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "440", "texto": "Os benefícios da legislação federal de serviços de guerra não são exigíveis dos Estados, sem que a lei estadual assim disponha.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "441", "texto": "O militar, que passa à inatividade com proventos integrais, não tem direito às cotas trigésimas a que se refere o Código de Vencimentos e Vantagens dos Militares.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "442", "texto": "A inscrição do contrato de locação no Registro de Imóveis, para a validade da cláusula de vigência contra o adquirente do imóvel, ou perante terceiros, dispensa a transcrição no Registro de Títulos e Documentos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "443", "texto": "A prescrição das prestações anteriores ao período previsto em lei não ocorre, quando não tiver sido negado, antes daquele prazo, o próprio direito reclamado, ou a situação jurídica de que ele resulta.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "445", "texto": "A Lei 2.437, de 7-3-1955, que reduz prazo prescricional, é aplicável às prescrições em curso na data de sua vigência (1º-1-1956), salvo quanto aos processos então pendentes.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "447", "texto": "É válida a disposição testamentária em favor de filho adulterino do testador com sua concubina.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "448", "texto": "O prazo para o assistente recorrer, supletivamente, começa a correr imediatamente após o transcurso do prazo do Ministério Público.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "449", "texto": "O valor da causa, na consignatória de aluguel, corresponde a uma anuidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "451", "texto": "A competência especial por prerrogativa de função não se estende ao crime cometido após a cessação definitiva do exercício funcional.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "452", "texto": "Oficiais e praças do Corpo de Bombeiros do Estado da Guanabara respondem perante a Justiça Comum por crime anterior à Lei 427, de 11-10-1948.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "453", "texto": "Não se aplicam à segunda instância o art. 384 e parágrafo único do Código de Processo Penal, que possibilitam dar nova definição jurídica ao fato delituoso, em virtude de circunstância elementar não contida, explícita ou implicitamente, na denúncia ou queixa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "454", "texto": "Simples interpretação de cláusulas contratuais não dá lugar a recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "455", "texto": "Da decisão que se seguir ao julgamento de constitucionalidade pelo Tribunal Pleno, são inadmissíveis embargos infringentes quanto à matéria constitucional.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "456", "texto": "O Supremo Tribunal Federal, conhecendo do recurso extraordinário, julgará a causa, aplicando o direito à espécie.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "457", "texto": "O Tribunal Superior do Trabalho, conhecendo da revista, julgará a causa, aplicando o direito à espécie.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "459", "texto": "No cálculo da indenização por despedida injusta, incluem-se os adicionais, ou gratificações, que, pela habitualidade, se tenham incorporado ao salário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "461", "texto": "É duplo, e não triplo, o pagamento do salário nos dias destinados a descanso.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "462", "texto": "No cálculo da indenização por despedida injusta inclui-se, quando devido, o repouso semanal remunerado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "463", "texto": "Para efeito de indenização e estabilidade, conta-se o tempo em que o empregado esteve afastado, em serviço militar obrigatório, mesmo anteriormente à L. 4.072, de 1.6.62.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "464", "texto": "No cálculo da indenização por acidente do trabalho inclui-se, quando devido, o repouso semanal remunerado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "465", "texto": "O regime de manutenção de salário, aplicável ao IAPM e ao IAPETC, exclui a indenização tarifada na Lei de Acidentes do Trabalho, mas não o benefício previdenciário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "466", "texto": "Não é inconstitucional a inclusão de sócios e administradores de sociedades e titulares de firmas individuais como contribuintes obrigatórios da previdência social.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "467", "texto": "A base do cálculo das contribuições previdenciárias, anteriormente à vigência da Lei Orgânica da Previdência Social, é o salário mínimo mensal, observados os limites da L. 2.755 de 1956.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "468", "texto": "Após a Emenda Constitucional 5 de 21-11-1961, em contrato firmado com a União, Estado, Município ou autarquia, é devido o impôsto federal de sêlo pelo contratante não protegido pela imunidade, ainda que haja repercussão do ônus tributário sôbre o patrimônio daquelas entidades.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "469", "texto": "A multa de cem por cento, para o caso de mercadoria importada irregularmente, é calculada à base do custo de câmbio da categoria correspondente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "470", "texto": "O imposto de transmissão \"inter vivos\" não incide sobre a construção, ou parte dela, realizada, inequivocamente, pelo promitente comprador, mas sobre o valor do que tiver sido construído antes da promessa de venda.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "471", "texto": "As empresas aeroviárias não estão isentas do imposto de indústrias e profissões.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "472", "texto": "A condenação do autor em honorários de advogado, com fundamento no art. 64 do C. P. C., depende de reconvenção.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "473", "texto": "A administração pode anular seus próprios atos, quando eivados de vícios que os tornam ilegais, porque deles não se originam direitos; ou revogá-los, por motivo de conveniência ou oportunidade, respeitados os direitos adquiridos, e ressalvada, em todos os casos, a apreciação judicial.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "474", "texto": "Não há direito líquido e certo, amparado pelo mandado de segurança, quando se escuda em lei cujos efeitos foram anulados por outra, declarada constitucional pelo Supremo Tribunal Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "475", "texto": "A Lei 4.686, de 21-6-1965, tem aplicação imediata aos processos em curso, inclusive em grau de recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "476", "texto": "Desapropriadas as ações de uma sociedade, o Poder desapropriante, imitido na posse, pode exercer, desde logo, todos os direitos inerentes aos respectivos títulos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "477", "texto": "As concessões de terras devolutas situadas na faixa de fronteira, feitas pelos Estados, autorizam, apenas, o uso, permanecendo o domínio com a União, ainda que se mantenha inerte ou tolerante, em relação aos possuidores.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "478", "texto": "O provimento em cargos de Juízes substitutos do Trabalho, deve ser feito independentemente de lista tríplice, na ordem de classificação dos candidatos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "479", "texto": "As margens dos rios navegáveis são de domínio público, insuscetíveis de expropriação e, por isso mesmo, excluídas de indenização.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "480", "texto": "Pertencem ao domínio e administração da União, nos termos dos arts. 4º, IV, e 186, da Constituição Federal de 1967, as terras ocupadas por silvículas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "481", "texto": "Se a locação compreende, além do imóvel, fundo de comércio, com instalações e pertences, como no caso de teatros, cinemas e hotéis, não se aplicam ao retomante as restrições do art. 8°, e, parágrafo único, do Decreto 24.150, de 20-4-1934.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "482", "texto": "O locatário, que não fôr sucessor ou cessionário do que o precedeu na locação, não pode somar os prazos concedidos a este, para pedir a renovação do contrato, nos termos do Decreto 24.150.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "483", "texto": "É dispensável a prova da necessidade, na retomada de prédio situado em localidade para onde o proprietário pretende transferir residência, salvo se mantiver, também, a anterior, quando dita prova será exigida.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "484", "texto": "Pode, legitimamente, o proprietário pedir o prédio para a residência de filho, ainda que solteiro, de acordo com o art. 11, III, da Lei 4.494, de 25-11-1964.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "485", "texto": "Nas locações regidas pelo Decreto 24.150, de 20-4-1934, a presunção de sinceridade do retomante é relativa, podendo ser ilidida pelo locatário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "486", "texto": "Admite-se a retomada para sociedade da qual o locador, ou seu cônjuge, seja sócio, com participação predominante no capital social.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "487", "texto": "Será deferida a posse a quem, evidentemente, tiver o domínio, se com base neste for ela disputada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "488", "texto": "A preferência a que se refere o art. 9° da Lei 3.912, de 3-7-1961, constitui direito pessoal. Sua violação resolve-se em perdas e danos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "489", "texto": "A compra e venda de automóvel não prevalece contra terceiros, de boa-fé, se o contrato não foi transcrito no registro de títulos e documentos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "490", "texto": "A pensão correspondente à indenização oriunda de responsabilidade civil deve ser calculada com base no salário mínimo vigente ao tempo da sentença e ajustar-se-á às variações ulteriores.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "491", "texto": "É indenizável o acidente que cause a morte de filho menor, ainda que não exerça trabalho remunerado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "492", "texto": "A empresa locadora de veículos responde, civil e solidariamente com o locatário, pelos danos por este causados a terceiro, no uso do carro locado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "493", "texto": "O valor da indenização, se consistente em prestações periódicas e sucessivas, compreenderá, para que se mantenha inalterável na sua fixação, parcelas compensatórias do imposto de renda, incidente sobre os juros do capital gravado ou caucionado, nos termos dos arts. 911 e 912 do Código de Processo Civil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "494", "texto": "A ação para anular venda de ascendente a descendente, sem consentimento dos demais, prescreve em vinte anos, contados da data do ato, revogada a Súmula 152.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "495", "texto": "A restituição em dinheiro da coisa vendida a crédito, entregue nos quinze dias anteriores ao pedido de falência ou de concordata, cabe, quando, ainda que consumida ou transformada, não faça o devedor prova de haver sido alienada a terceiro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "496", "texto": "São válidos, porque salvaguardados pelas Disposições Constitucionais Transitórias da Constituição Federal de 1967, os decretos-leis expedidos entre 24 de janeiro e 15 de março de 1967.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "497", "texto": "Quando se tratar de crime continuado, a prescrição regula-se pela pena imposta na sentença, não se computando o acréscimo decorrente da continuação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "499", "texto": "Não obsta à concessão do \"sursis\" condenação anterior à pena de multa. Jurisprudência selecionada ● Concessão do sursis e condenação anterior à pena de multa Habeas Corpus. Condenação a pena de um ano e dois meses de reclusão, Códido Penal , art. 155. 2. Negativa do \"sursis\", porque reincidente o réu. 3. Hipótese em que, anteriormente, o paciente fora condenado a pena de detenção substituída por multa. 4. Pena de multa, em condenação anterior, não impede a concessão do \"sursis\". Código Penal. Art. 77, par. 1. 5. Habeas Corpus deferido, em parte, em ordem a, mantida a condenação, anular a sentença condenatória e o acórdão que a confirmou, para que outra decisão se profira, motivadamente, no que concerne aos requisitos objetivos e subjetivos do \"sursis\", a fim de concede-lo ou não, afastada, no caso, a reincidencia. [ HC 72.605 , rel. min. Néri da Silveira , 2ª T, j. 17-10-1995, DJ de 7-12-1995.] Habeas Corpus. Re condenada a dois anos de reclusão. \"Sursis\". Condenação anterior a pena de multa não impede a concessão do benefício. Código Penal , art. 77, par. 1. Hipótese em que, em grau de apelação, veio, ainda, a ser declarada extinta a punibilidade pela prescrição da pretensão punitiva. Essa anterior condenação não marca, assim, os antecedentes do réu, nem gera futura reincidencia. Não havia dessa maneira, amparo legal para o acórdão cassar o \"sursis\" concedido na sentença, onde condenada a paciente a dois anos de reclusão. Habeas Corpus deferido, para restabelecer o \"sursis\" concedido na decisão de primeiro grau. [ HC 69.918 , rel. min. Néri da Silveira , 2ª T, j. 2-3-1993, DJ de 26-3-1993.] Habeas Corpus. Suspensão condicional da pena. Apelação em liberdade. I - Não se pode negar \"sursis\" ao argumento da reincidencia se a condenação anterior foi meramente pecuniária. (...). [ RHC 66.900 , rel. min. Francisco Rezek , 2ª T, j. 8-11-1988, DJ de 2-12-1988.]", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "500", "texto": "Não cabe a ação cominatória para compelir-se o réu a cumprir obrigação de dar.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "501", "texto": "Compete à Justiça Ordinária Estadual o processo e o julgamento, em ambas as instâncias, das causas de acidente do trabalho, ainda que promovidas contra a União, suas autarquias, empresas públicas ou sociedades de economia mista.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "502", "texto": "Na aplicação do art. 839 do Código de Processo Civil, com a redação da Lei 4.290, de 5-12-1963, a relação valor da causa e salário mínimo vigente na capital do Estado, ou do Território, para efeito de alçada, deve ser considerada na data do ajuizamento do pedido.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "503", "texto": "A dúvida, suscitada por particular, sobre o direito de tributar, manifestado por dois Estados, não configura litígio da competência originária do Supremo Tribunal Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "504", "texto": "Compete à Justiça Federal, em ambas as instâncias, o processo e o julgamento das causas fundadas em contrato de seguro marítimo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "505", "texto": "Salvo quando contrariarem a Constituição, não cabe recurso para o Supremo Tribunal Federal, de quaisquer decisões da Justiça do Trabalho, inclusive dos presidentes de seus tribunais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "506", "texto": "O agravo a que se refere o art. 4º da Lei 4.348, de 26-6-1964, cabe, somente, do despacho do Presidente do Supremo Tribunal Federal que defere a suspensão da liminar, em mandado de segurança; não do que a \"denega\".", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "507", "texto": "A ampliação dos prazos a que se refere o art. 32 do Código de Processo Civil aplica-se aos executivos fiscais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "508", "texto": "Compete à Justiça Estadual, em ambas as instâncias, processar e julgar as causas em que for parte o Banco do Brasil S.A.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "509", "texto": "A Lei 4.632, de 18-05-1965, que alterou o art. 64 do Código de Processo Civil, aplica-se aos processos em andamento, nas instâncias ordinárias.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "510", "texto": "Praticado o ato por autoridade, no exercício de competência delegada, contra ela cabe o mandado de segurança ou a medida judicial.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "511", "texto": "Compete à Justiça Federal, em ambas as instâncias, processar e julgar as causas entre autarquias federais e entidades públicas locais, inclusive mandados de segurança, ressalvada a ação fiscal, nos termos da Constituição Federal de 1967, art. 119, § 3º.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "512", "texto": "Não cabe condenação em honorários de advogado na ação de mandado de segurança.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "513", "texto": "A decisão que enseja a interposição de recurso ordinário ou extraordinário não é a do plenário, que resolve o incidente de inconstitucionalidade, mas a do órgão (câmaras, grupos ou turmas) que completa o julgamento do feito.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "514", "texto": "Admite-se ação rescisória contra sentença transitada em julgado, ainda que contra ela não se tenha esgotado todos os recursos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "515", "texto": "A competência para a ação rescisória não é do Supremo Tribunal Federal, quando a questão federal, apreciada no recurso extraordinário ou no agravo de instrumento, seja diversa da que foi suscitada no pedido rescisório.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "516", "texto": "O Serviço Social da Indústria (SESI) está sujeito à jurisdição da Justiça estadual.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "517", "texto": "As sociedades de economia mista só têm foro na Justiça Federal, quando a União intervém como assistente ou opoente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "518", "texto": "A intervenção da União, em feito já julgado pela segunda instância e pendente de embargos, não desloca o processo para o Tribunal Federal de Recursos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "519", "texto": "Aplica-se aos executivos fiscais o princípio da sucumbência a que se refere o art. 64 do Código de Processo Civil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "520", "texto": "Não exige a lei que, para requerer o exame a que se refere o art. 777 do Código de Processo Penal, tenha o sentenciado cumprido mais de metade do prazo da medida de segurança imposta.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "521", "texto": "O foro competente para o processo e julgamento dos crimes de estelionato, sob a modalidade da emissão dolosa de cheque sem provisão de fundos, é o do local onde se deu a recusa do pagamento pelo sacado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "522", "texto": "Salvo ocorrência de tráfico para o exterior, quando, então, a competência será da justiça federal, compete à justiça dos estados o processo e julgamento dos crimes relativos a entorpecentes.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "523", "texto": "No processo penal, a falta da defesa constitui nulidade absoluta, mas a sua deficiência só o anulará se houver prova de prejuízo para o réu.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "524", "texto": "Arquivado o inquérito policial, por despacho do juiz, a requerimento do promotor de justiça, não pode a ação penal ser iniciada, sem novas provas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "525", "texto": "A medida de segurança não será aplicada em segunda instância, quando só o réu tenha recorrido.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "526", "texto": "Subsiste a competência do Supremo Tribunal Federal para conhecer e julgar a apelação, nos crimes da Lei de Segurança Nacional, se houve sentença antes da vigência do A.I. n° 2.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "527", "texto": "Após a vigência do Ato Institucional 6, que deu nova redação ao art. 114, III, da Constituição Federal de 1967, não cabe recurso extraordinário das decisões do juiz singular.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "528", "texto": "Se a decisão contiver partes autônomas, a admissão parcial, pelo presidente do tribunal a quo , de recurso extraordinário que, sobre qualquer delas se manifestar, não limitará a apreciação de todas pelo Supremo Tribunal Federal, independentemente de interposição de agravo de instrumento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "529", "texto": "Subsiste a responsabilidade do empregador pela indenização decorrente de acidente do trabalho, quando o segurador, por haver entrado em liquidação, ou por outro motivo, não se encontrar em condições financeiras, de efetuar, na forma da lei, o pagamento que o seguro obrigatório visava garantir.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "530", "texto": "Na legislação anterior ao art. 4º da Lei 4.749, de 12-08-1965, a contribuição para a previdência social não estava sujeita ao limite estabelecido no art. 69 da Lei 3.807, de 26-08-1960, sobre o 13º salário a que se refere o art. 3º da Lei 4.281, de 8-11-1963.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "531", "texto": "É inconstitucional o Decreto 51668, de 17-01-1963, que estabeleceu salário profissional para trabalhadores de transportes marítimos, fluviais e lacustres.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "532", "texto": "É constitucional a Lei 5.043, de 21-06-1966, que concedeu remissão das dívidas fiscais oriundas da falta de oportuno pagamento de sêlo nos contratos particulares com a Caixa Econômica e outras entidades autárquicas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "533", "texto": "Nas operações denominadas \"crediários\", com emissão de vales ou certificados para compras e nas quais, pelo financiamento, se cobram, em separado, juros, selos e outras despesas, incluir-se-á tudo no custo da mercadoria e sôbre esse preço global calcular-se-á o impôsto de vendas e consignações.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "534", "texto": "O imposto de importação sobre o extrato alcoólico de malte, como matéria-prima para fabricação de whisky , incide à base de 60%, desde que desembarcado antes do Decreto-lei 398, de 30-12-1968.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "535", "texto": "Na importação, a granel, de combustíveis líquidos é admíssivel a diferença de pêso, para mais, até 4%, motivada pelas variações previstas no Decreto-lei 1.028, de 4-1-1939, art. 1º.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "536", "texto": "São objetivamente imunes ao imposto sobre circulação de mercadorias os \"produtos industrializados\", em geral, destinados à exportação, além de outros, com a mesma destinação, cuja isenção a lei determinar.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "537", "texto": "É inconstitucional a exigência de impôsto estadual do sêlo, quando feita nos atos e instrumentos tributados ou regulados por lei federal, ressalvado o disposto no art. 15, § 5º, da Constituição Federal de 1946.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "538", "texto": "A avaliação judicial para o efeito do cálculo das benfeitorias dedutíveis do impôsto sôbre lucro imobiliário independe do limite a que se refere a Lei 3.470, de 28-11-1958, art. 8º, parágrafo único.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "539", "texto": "É constitucional a lei do Município que reduz o imposto predial urbano sobre imóvel ocupado pela residência do proprietário, que não possua outro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "540", "texto": "No preço da mercadoria sujeita ao imposto de vendas e consignações, não se incluem as despesas de frete e carreto.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "541", "texto": "O imposto sobre vendas e consignações não incide sobre a venda ocasional de veículos e equipamentos usados, que não se insere na atividade profissional do vendedor, e não é realizada com o fim de lucro, sem caráter, pois, de comercialidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "542", "texto": "Não é inconstitucional a multa instituída pelo Estado-membro, como sanção pelo retardamento do início ou da ultimação do inventário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "543", "texto": "A Lei 2.975, de 27-11-1965, revogou, apenas, as isenções de caráter geral, relativas ao impôsto único sôbre combustíveis, não as especiais, por outras leis concedidas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "544", "texto": "Isenções tributárias concedidas, sob condição onerosa, não podem ser livremente suprimidas.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "545", "texto": "Preços de serviços públicos e taxas não se confundem, porque estas, diferentemente daqueles, são compulsórias e têm sua cobrança condicionada à prévia autorização orçamentária, em relação à lei que as instituiu.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "546", "texto": "Cabe a restituição do tributo pago indevidamente, quando reconhecido por decisão, que o contribuinte \"de jure\" não recuperou do contribuinte \"de facto\" o \"quantum\" respectivo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "547", "texto": "Não é lícito à autoridade proibir que o contribuinte em débito adquira estampilhas, despache mercadorias nas alfândegas e exerça suas atividades profissionais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "548", "texto": "É inconstitucional o Decreto-lei 643, de 19-6-1947, artigo 4º, do Paraná, na parte que exige sêlo proporcional sôbre atos e instrumentos regulados por lei federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "549", "texto": "A taxa de bombeiros do Estado de Pernambuco é constitucional, revogada a Súmula 274.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "550", "texto": "A isenção concedida pelo art. 2º da Lei 1.815 de 1953, às emprêsas de navegação aérea não compreende a taxa de melhoramento de portos, instituída pela Lei 3.421 de 1958.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "551", "texto": "É inconstitucional a taxa de urbanização da Lei 2.320, de 20-12-1961, instituída pelo Município de Pôrto Alegre, porque seu fato gerador é o mesmo da transmissão imobiliária.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "552", "texto": "Com a regulamentação do art. 15 da Lei 5.316/1967, pelo Decreto 71.037/1972, tornou-se exequível a exigência da exaustão da via administrativa antes do início da ação de acidente do trabalho.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "553", "texto": "O Adicional ao Frete para Renovação da Marinha Mercante (AFRMM) é contribuição parafiscal, não sendo abrangido pela imunidade prevista na letra \"d\", III, do art. 19 da Constituição Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "554", "texto": "O pagamento de cheque emitido sem provisão de fundos, após o recebimento da denúncia, não obsta ao prosseguimento da ação penal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "555", "texto": "É competente o Tribunal de Justiça para julgar conflito de jurisdição entre Juiz de Direito do Estado e a Justiça Militar local.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "556", "texto": "É competente a Justiça Comum para julgar as causas em que é parte sociedade de economia mista.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "557", "texto": "É competente a Justiça Federal para julgar as causas em que são partes a COBAL e a CIBRAZEM.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "558", "texto": "É constitucional o art. 27 do Decreto-lei 898, de 29-9-1969.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "559", "texto": "O Decreto-lei 730, de 5-8-1969, revogou a exigência de homologação, pelo Ministro da Fazenda, das Resoluções do Conselho de Política Aduaneira.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "560", "texto": "A extinção de punibilidade, pelo pagamento do tributo devido, estende-se ao crime de contrabando ou descaminho, por força do art. 18, § 2º, do Decreto-Lei 157/1967.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "561", "texto": "Em desapropriação, é devida a correção monetária até a data do efetivo pagamento da indenização, devendo proceder-se à atualização do cálculo, ainda que por mais de uma vez.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "562", "texto": "Na indenização de danos materiais decorrentes de ato ilícito cabe a atualização de seu valor, utilizando-se, para esse fim, dentre outros critérios, dos índices de correção monetária.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "563", "texto": "O concurso de preferência a que se refere o parágrafo único do art. 187 do Código Tributário Nacional é compatível com o disposto no art. 9º, I, da Constituição Federal. (cancelada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "564", "texto": "A ausência de fundamentação do despacho de recebimento de denúncia por crime falimentar enseja nulidade processual, salvo se já houver sentença condenatória.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "565", "texto": "A multa fiscal moratória constitui pena administrativa, não se incluindo no crédito habilitado em falência.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "566", "texto": "Enquanto pendente, o pedido de readaptação fundado em desvio funcional não gera direitos para o servidor, relativamente ao cargo pleiteado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "567", "texto": "A Constituição, ao assegurar, no § 3º do art. 102, a contagem integral do tempo de serviço público federal, estadual ou municipal para os efeitos de aposentadoria e disponibilidade não proíbe à União, aos Estados e aos Municípios mandarem contar, mediante lei, para efeito diverso, tempo de serviço prestado a outra pessoa de direito público interno.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "568", "texto": "A identificação criminal não constitui constrangimento ilegal, ainda que o indiciado já tenha sido identificado civilmente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "569", "texto": "É inconstitucional a discriminação de alíquotas do imposto de circulação de mercadorias nas operações interestaduais, em razão de o destinatário ser, ou não, contribuinte.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "570", "texto": "O imposto de circulação de mercadorias não incide sobre a importação de bens de capital.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "571", "texto": "O comprador de café ao IBC, ainda que sem expedição de nota fiscal, habilita-se, quando da comercialização do produto, ao crédito do ICM que incidiu sobre a operação anterior.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "572", "texto": "No cálculo do imposto de circulação de mercadorias devido na saída de mercadorias para o exterior, não se incluem fretes pagos a terceiros, seguros e despesas de embarque.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "574", "texto": "Sem lei estadual que a estabeleça, é ilegítima a cobrança do imposto de circulação de mercadorias sobre o fornecimento de alimentação e bebidas em restaurante ou estabelecimento similar.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "575", "texto": "À mercadoria importada de país signatário do GATT, ou membro da ALALC, estende-se a isenção do imposto sobre circulação de mercadorias concedida a similar nacional.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "576", "texto": "É lícita a cobrança do imposto sobre circulação de mercadorias sobre produtos importados sob o regime da alíquota \"zero\".", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "577", "texto": "Na importação de mercadorias do exterior, o fato gerador do imposto de circulação de mercadorias ocorre no momento de sua entrada no estabelecimento do importador.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "578", "texto": "Não podem os Estados, a título de ressarcimento de despesas, reduzir a parcela de 20% do produto da arrecadação do imposto de circulação de mercadorias, atribuída aos Municípios pelo art. 23, § 8º, da Constituição Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "579", "texto": "A cal virgem e a hidratada estão sujeitas ao imposto de circulação de mercadorias.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "580", "texto": "A isenção prevista no art. 13, parágrafo único, do Decreto-lei 43/1966, restringe-se aos filmes cinematográficos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "581", "texto": "A exigência de transporte em navio de bandeira brasileira, para efeito de isenção tributária, legitimou-se com o advento do Decreto-lei nº 666, de 2-7-1969.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "582", "texto": "É constitucional a Resolução nº 640/69, do Conselho de Política Aduaneira, que reduziu a alíquota do imposto de importação para a soda cáustica, destinada a zonas de difícil distribuição e abastecimento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "583", "texto": "Promitente comprador de imóvel residencial transcrito em nome de autarquia é contribuinte do imposto predial territorial urbano.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "584", "texto": "Ao imposto de renda calculado sobre os rendimentos do ano-base, aplica-se a lei vigente no exercício financeiro em que deve ser apresentada a declaração. (cancelada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "585", "texto": "Não incide o imposto de renda sobre a remessa de divisas para pagamento de serviços prestados no exterior, por empresa que não opera no Brasil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "586", "texto": "Incide imposto de renda sobre os juros remetidos para o exterior, com base em contrato de mútuo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "587", "texto": "Incide imposto de renda sobre o pagamento de serviços técnicos contratados no exterior e prestados no Brasil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "588", "texto": "O imposto sobre serviços não incide sobre os depósitos, as comissões e taxas de desconto, cobrados pelos estabelecimentos bancários.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "589", "texto": "É inconstitucional a fixação de adicional progressivo do imposto predial e territorial urbano em função do número de imóveis do contribuinte.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "590", "texto": "Calcula-se o imposto de transmissão causa mortis sobre o saldo credor da promessa de compra e venda de imóvel, no momento da abertura da sucessão do promitente vendedor.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "591", "texto": "A imunidade ou a isenção tributária do comprador não se estende ao produtor, contribuinte do imposto sobre produtos industrializados.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "592", "texto": "Nos crimes falimentares, aplicam-se as causas interruptivas da prescrição, previstas no Código Penal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "593", "texto": "Incide o percentual do Fundo de Garantia do Tempo de Serviço (FGTS) sobre a parcela da remuneração correspondente a horas extraordinárias de trabalho.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "594", "texto": "Os direitos de queixa e de representação podem ser exercidos, independentemente, pelo ofendido ou por seu representante legal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "595", "texto": "É inconstitucional a taxa municipal de conservação de estradas de rodagem cuja base de cálculo seja idêntica à do imposto territorial rural.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "596", "texto": "As disposições do Decreto 22.626/1933 não se aplicam às taxas de juros e aos outros encargos cobrados nas operações realizadas por instituições públicas ou privadas, que integram o Sistema Financeiro Nacional.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "597", "texto": "Não cabem embargos infringentes de acórdão que, em mandado de segurança, decidiu, por maioria de votos, a apelação.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "598", "texto": "Nos embargos de divergência não servem como padrão de discordância os mesmos paradigmas invocados para demonstrá-la mas repelidos como não dissidentes no julgamento do recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "599", "texto": "São incabíveis embargos de divergência de decisão de Turma, em Agravo Regimental. (cancelada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "600", "texto": "Cabe ação executiva contra o emitente e seus avalistas, ainda que não apresentado o cheque ao sacado no prazo legal, desde que não prescrita a ação cambiária.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "601", "texto": "Os arts. 3°, II, e 55 da Lei Complementar 40/1981 (Lei Orgânica do Ministério Público) não revogaram a legislação anterior que atribui a iniciativa para a ação penal pública, no processo sumário, ao juiz ou à autoridade policial, mediante Portaria ou Auto de Prisão em Flagrante.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "602", "texto": "Nas causas criminais, o prazo de interposição de Recurso Extraordinário é de 10 (dez) dias.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "603", "texto": "A competência para o processo e julgamento de latrocínio é do juiz singular e não do tribunal do júri.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "604", "texto": "A prescrição pela pena em concreto é somente da pretensão executória da pena privativa de liberdade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "605", "texto": "Não se admite continuidade delitiva nos crimes contra a vida.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "606", "texto": "Não cabe habeas corpus originário para o Tribunal Pleno de decisão de Turma, ou do Plenário, proferida em habeas corpus ou no respectivo recurso.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "607", "texto": "Na ação penal regida pela Lei 4.611/1965, a denúncia, como substitutivo da portaria, não interrompe a prescrição.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "608", "texto": "No crime de estupro, praticado mediante violência real, a ação penal é pública incondicionada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "609", "texto": "É pública incondicionada a ação penal por crime de sonegação fiscal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "610", "texto": "Há crime de latrocínio, quando o homicídio se consuma, ainda que não realize o agente a subtração de bens da vítima.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "611", "texto": "Transitada em julgado a sentença condenatória, compete ao juízo das execuções a aplicação de lei mais benigna.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "612", "texto": "Ao trabalhador rural não se aplicam, por analogia, os benefícios previstos na Lei nº 6367, de 19/10/76.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "613", "texto": "Os dependentes de trabalhador rural não têm direito à pensão previdenciária, se o óbito ocorreu anteriormente à vigência da Lei Complementar 11/1971.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "614", "texto": "Somente o Procurador-Geral da Justiça tem legitimidade para propor ação direta interventiva por inconstitucionalidade de Lei Municipal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "615", "texto": "O princípio constitucional da anualidade (§ 29 do art. 153 da Constituição Federal) não se aplica à revogação de isenção do ICM.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "616", "texto": "É permitida a cumulação da multa contratual com os honorários de advogado, após o advento do Código de Processo Civil vigente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "617", "texto": "A base de cálculo dos honorários de advogado em desapropriação é a diferença entre a oferta e a indenização, corrigidas ambas monetariamente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "618", "texto": "Na desapropriação, direta ou indireta, a taxa dos juros compensatórios é de 12% (doze por cento) ao ano.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "619", "texto": "A prisão do depositário judicial pode ser decretada no próprio processo em que se constituiu o encargo, independentemente da propositura de ação de depósito. (revogada)", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "620", "texto": "A sentença proferida contra Autarquias não está sujeita a reexame necessário, salvo quando sucumbente em execução de dívida ativa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "621", "texto": "Não enseja Embargos de Terceiro à penhora a promessa de compra e venda não inscrita no registro de imóveis.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "622", "texto": "Não cabe Agravo Regimental contra decisão do relator que concede ou indefere liminar em Mandado de Segurança.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "623", "texto": "Não gera por si só a competência originária do Supremo Tribunal Federal para conhecer do mandado de segurança com base no art. 102, I, \"n\", da Constituição, dirigir-se o pedido contra deliberação administrativa do tribunal de origem, da qual haja participado a maioria ou a totalidade de seus membros.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "624", "texto": "Não compete ao Supremo Tribunal Federal conhecer originariamente de mandado de segurança contra atos de outros tribunais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "625", "texto": "Controvérsia sobre matéria de direito não impede concessão de mandado de segurança.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "626", "texto": "A suspensão da liminar em mandado de segurança, salvo determinação em contrário da decisão que a deferir, vigorará até o trânsito em julgado da decisão definitiva de concessão da segurança ou, havendo recurso, até a sua manutenção pelo Supremo Tribunal Federal, desde que o objeto da liminar deferida coincida, total ou parcialmente, com o da impetração.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "627", "texto": "No mandado de segurança contra a nomeação de magistrado da competência do Presidente da República, este é considerado autoridade coatora, ainda que o fundamento da impetração seja nulidade ocorrida em fase anterior do procedimento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "628", "texto": "Integrante de lista de candidatos a determinada vaga da composição de tribunal é parte legítima para impugnar a validade da nomeação de concorrente.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "629", "texto": "A impetração de mandado de segurança coletivo por entidade de classe em favor dos associados independe da autorização destes.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "630", "texto": "A entidade de classe tem legitimação para o mandado de segurança ainda quando a pretensão veiculada interesse apenas a uma parte da respectiva categoria.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "631", "texto": "Extingue-se o processo de mandado de segurança se o impetrante não promove, no prazo assinado, a citação do litisconsorte passivo necessário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "632", "texto": "É constitucional lei que fixa o prazo de decadência para a impetração de mandado de segurança.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "633", "texto": "É incabível a condenação em verba honorária nos recursos extraordinários interpostos em processo trabalhista, exceto nas hipóteses previstas na Lei 5584/1970.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "634", "texto": "Não compete ao Supremo Tribunal Federal conceder medida cautelar para dar efeito suspensivo a recurso extraordinário que ainda não foi objeto de juízo de admissibilidade na origem.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "635", "texto": "Cabe ao presidente do tribunal de origem decidir o pedido de medida cautelar em recurso extraordinário ainda pendente do seu juízo de admissibilidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "636", "texto": "Não cabe recurso extraordinário por contrariedade ao princípio constitucional da legalidade, quando a sua verificação pressuponha rever a interpretação dada a normas infraconstitucionais pela decisão recorrida.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "637", "texto": "Não cabe recurso extraordinário contra acórdão de tribunal de justiça que defere pedido de intervenção estadual em município.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "638", "texto": "A controvérsia sobre a incidência, ou não, de correção monetária em operações de crédito rural é de natureza infraconstitucional, não viabilizando recurso extraordinário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "639", "texto": "Aplica-se a Súmula 288 quando não constarem do traslado do agravo de instrumento as cópias das peças necessárias à verificação da tempestividade do recurso extraordinário não admitido pela decisão agravada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "640", "texto": "É cabível recurso extraordinário contra decisão proferida por juiz de primeiro grau nas causas de alçada, ou por turma recursal de juizado especial cível e criminal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "641", "texto": "Não se conta em dobro o prazo para recorrer, quando só um dos litisconsortes haja sucumbido.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "642", "texto": "Não cabe ação direta de inconstitucionalidade de lei do Distrito Federal derivada da sua competência legislativa municipal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "643", "texto": "O Ministério Público tem legitimidade para promover ação civil pública cujo fundamento seja a ilegalidade de reajuste de mensalidades escolares.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "644", "texto": "Ao titular do cargo de procurador de autarquia não se exige a apresentação de instrumento de mandato para representá-la em juízo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "645", "texto": "É competente o município para fixar o horário de funcionamento de estabelecimento comercial.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "646", "texto": "Ofende o princípio da livre concorrência lei municipal que impede a instalação de estabelecimentos comerciais do mesmo ramo em determinada área.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "647", "texto": "Compete privativamente à União legislar sobre vencimentos dos membros das polícias civil e militar do Distrito Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "648", "texto": "A norma do § 3º do art. 192 da Constituição, revogada pela Emenda Constitucional 40/2003, que limitava a taxa de juros reais a 12% ao ano, tinha sua aplicabilidade condicionada à edição de Lei Complementar.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "649", "texto": "É inconstitucional a criação, por Constituição Estadual, de órgão de controle administrativo do Poder Judiciário do qual participem representantes de outros poderes ou entidades.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "650", "texto": "Os incisos I e XI do art. 20 da Constituição Federal não alcançam terras de aldeamentos extintos, ainda que ocupadas por indígenas em passado remoto.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "651", "texto": "A medida provisória não apreciada pelo Congresso Nacional podia, até a Emenda Constitucional 32/2001, ser reeditada dentro do seu prazo de eficácia de trinta dias, mantidos os efeitos de lei desde a primeira edição.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "652", "texto": "Não contraria a Constituição o art. 15, § 1º, do Decreto-lei 3365/1941 (Lei da desapropriação por utilidade pública).", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "653", "texto": "No Tribunal de Contas Estadual, composto por sete conselheiros, quatro devem ser escolhidos pela Assembléia Legislativa e três pelo chefe do Poder Executivo estadual, cabendo a este indicar um dentre auditores e outro dentre membros do Ministério Público, e um terceiro a sua livre escolha.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "654", "texto": "A garantia da irretroatividade da lei, prevista no art. 5º, XXXVI, da Constituição da República, não é invocável pela entidade estatal que a tenha editado.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "655", "texto": "A exceção prevista no art. 100, caput, da Constituição, em favor dos créditos de natureza alimentícia, não dispensa a expedição de precatório, limitando-se a isentá-los da observância da ordem cronológica dos precatórios decorrentes de condenações de outra natureza.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "656", "texto": "É inconstitucional a lei que estabelece alíquotas progressivas para o imposto de transmissão inter vivos de bens imóveis - ITBI com base no valor venal do imóvel.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "657", "texto": "A imunidade prevista no art. 150, VI, \"d\", da Constituição Federal abrange os filmes e papéis fotográficos necessários à publicação de jornais e periódicos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "658", "texto": "São constitucionais os arts. 7º da Lei 7.787/1989 e 1º da Lei 7.894/1989 e da Lei 8.147/1990, que majoraram a alíquota do FINSOCIAL, quando devida a contribuição por empresas dedicadas exclusivamente à prestação de serviços.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "659", "texto": "É legítima a cobrança da Cofins, do PIS e do Finsocial sobre as operações relativas a energia elétrica, serviços de telecomunicações, derivados de petróleo, combustíveis e minerais do país.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "660", "texto": "Não incide ICMS na importação de bens por pessoa física ou jurídica que não seja contribuinte do imposto.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "661", "texto": "Na entrada de mercadoria importada do exterior, é legítima a cobrança do ICMS por ocasião do desembaraço aduaneiro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "662", "texto": "É legítima a incidência do ICMS na comercialização de exemplares de obras cinematográficas, gravados em fitas de videocassete.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "663", "texto": "Os §§ 1º e 3º do art. 9º do Decreto-Lei 406/1968 foram recebidos pela Constituição.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "664", "texto": "É inconstitucional o inciso V do art. 1º da Lei 8.033/1990, que instituiu a incidência do imposto nas operações de crédito, câmbio e seguros - IOF sobre saques efetuados em caderneta de poupança.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "665", "texto": "É constitucional a taxa de fiscalização dos mercados de títulos e valores mobiliários instituída pela Lei 7.940/1989.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "666", "texto": "A contribuição confederativa de que trata o art. 8º, IV, da Constituição, só é exigível dos filiados ao sindicato respectivo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "667", "texto": "Viola a garantia constitucional de acesso à jurisdição a taxa judiciária calculada sem limite sobre o valor da causa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "668", "texto": "É inconstitucional a lei municipal que tenha estabelecido, antes da Emenda Constitucional 29/2000, alíquotas progressivas para o IPTU, salvo se destinada a assegurar o cumprimento da função social da propriedade urbana.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "669", "texto": "Norma legal que altera o prazo de recolhimento da obrigação tributária não se sujeita ao princípio da anterioridade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "670", "texto": "O serviço de iluminação pública não pode ser remunerado mediante taxa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "671", "texto": "Os servidores públicos e os trabalhadores em geral têm direito, no que concerne à URP de abril/maio de 1988, apenas ao valor correspondente a 7/30 de 16,19% sobre os vencimentos e salários pertinentes aos meses de abril e maio de 1988, não cumulativamente, devidamente corrigido até o efetivo pagamento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "672", "texto": "O reajuste de 28,86%, concedido aos servidores militares pelas leis 8622/1993 e 8627/1993, estende-se aos servidores civis do Poder Executivo, observadas as eventuais compensações decorrentes dos reajustes diferenciados concedidos pelos mesmos diplomas legais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "673", "texto": "O art. 125, § 4º, da Constituição não impede a perda da graduação de militar mediante procedimento administrativo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "674", "texto": "A anistia prevista no art. 8º do Ato das Disposições Constitucionais Transitórias não alcança os militares expulsos com base em legislação disciplinar ordinária, ainda que em razão de atos praticados por motivação política.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "675", "texto": "Os intervalos fixados para descanso e alimentação durante a jornada de seis horas não descaracterizam o sistema de turnos ininterruptos de revezamento para o efeito do art. 7º, XIV, da Constituição.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "676", "texto": "A garantia da estabilidade provisória prevista no art. 10, II, \"a\", do Ato das Disposições Constitucionais Transitórias, também se aplica ao suplente do cargo de direção de comissões internas de prevenção de acidentes (CIPA).", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "677", "texto": "Até que lei venha a dispor a respeito, incumbe ao Ministério do Trabalho proceder ao registro das entidades sindicais e zelar pela observância do princípio da unicidade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "678", "texto": "São inconstitucionais os incisos I e III do art. 7º da Lei 8.162/91, que afastam, para efeito de anuênio e de licença-prêmio, a contagem do tempo de serviço regido pela consolidação das leis do trabalho dos servidores que passaram a submeter-se ao regime jurídico único.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "679", "texto": "A fixação de vencimentos dos servidores públicos não pode ser objeto de convenção coletiva.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "680", "texto": "O direito ao auxílio-alimentação não se estende aos servidores inativos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "681", "texto": "É inconstitucional a vinculação do reajuste de vencimentos de servidores estaduais ou municipais a índices federais de correção monetária.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "682", "texto": "Não ofende a Constituição a correção monetária no pagamento com atraso dos vencimentos dos servidores públicos.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "683", "texto": "O limite de idade para a inscrição em concurso público só se legitima em face do art. 7º, XXX, da Constituição, quando possa ser justificado pela natureza das atribuições do cargo a ser preenchido.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "684", "texto": "É inconstitucional o veto não motivado à participação de candidato a concurso público.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "685", "texto": "É inconstitucional toda modalidade de provimento que propicie ao servidor investir-se, sem prévia aprovação em concurso público destinado ao seu provimento, em cargo que não integra a carreira na qual anteriormente investido.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "686", "texto": "Só por lei se pode sujeitar a exame psicotécnico a habilitação de candidato a cargo público.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "687", "texto": "A revisão de que trata o art. 58 do Ato das Disposições Constitucionais Transitórias não se aplica aos benefícios previdenciários concedidos após a promulgação da Constituição de 1988.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "688", "texto": "É legítima a incidência da contribuição previdenciária sobre o 13º salário.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "689", "texto": "O segurado pode ajuizar ação contra a instituição previdenciária perante o Juízo Federal do seu domicílio ou nas Varas Federais da capital do Estado-membro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "690", "texto": "Compete originariamente ao Supremo Tribunal Federal o julgamento de \"habeas corpus\" contra decisão de Turma Recursal de Juizados Especiais Criminais.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "691", "texto": "Não compete ao Supremo Tribunal Federal conhecer de habeas corpus impetrado contra decisão do relator que, em habeas corpus requerido a tribunal superior, indefere a liminar.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "692", "texto": "Não se conhece de habeas corpus contra omissão de relator de extradição, se fundado em fato ou direito estrangeiro cuja prova não constava dos autos, nem foi ele provocado a respeito.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "693", "texto": "Não cabe habeas corpus contra decisão condenatória a pena de multa, ou relativo a processo em curso por infração penal a que a pena pecuniária seja a única cominada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "694", "texto": "Não cabe habeas corpus contra a imposição da pena de exclusão de militar ou de perda de patente ou de função pública.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "695", "texto": "Não cabe habeas corpus quando já extinta a pena privativa de liberdade.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "696", "texto": "Reunidos os pressupostos legais permissivos da suspensão condicional do processo, mas se recusando o promotor de justiça a propô-la, o juiz, dissentindo, remeterá a questão ao Procurador-Geral, aplicando-se por analogia o art. 28 do Código de Processo Penal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "697", "texto": "A proibição de liberdade provisória nos processos por crimes hediondos não veda o relaxamento da prisão processual por excesso de prazo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "698", "texto": "Não se estende aos demais crimes hediondos a admissibilidade de progressão no regime de execução da pena aplicada ao crime de tortura.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "699", "texto": "O prazo para interposição de agravo, em processo penal, é de cinco dias, de acordo com a Lei 8.038/1990, não se aplicando o disposto a respeito nas alterações da Lei 8.950/1994 ao Código de Processo Civil.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "700", "texto": "É de cinco dias o prazo para interposição de agravo contra decisão do juiz da execução penal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "701", "texto": "No mandado de segurança impetrado pelo Ministério Público contra decisão proferida em processo penal, é obrigatória a citação do réu como litisconsorte passivo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "702", "texto": "A competência do tribunal de justiça para julgar prefeitos restringe-se aos crimes de competência da justiça comum estadual; nos demais casos, a competência originária caberá ao respectivo tribunal de segundo grau.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "703", "texto": "A extinção do mandato do prefeito não impede a instauração de processo pela prática dos crimes previstos no art. 1º do DL 201/1967.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "704", "texto": "Não viola as garantias do juiz natural, da ampla defesa e do devido processo legal a atração por continência ou conexão do processo do corréu ao foro por prerrogativa de função de um dos denunciados.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "705", "texto": "A renúncia do réu ao direito de apelação, manifestada sem a assistência do defensor, não impede o conhecimento da apelação por este interposta.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "706", "texto": "É relativa a nulidade decorrente da inobservância da competência penal por prevenção.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "707", "texto": "Constitui nulidade a falta de intimação do denunciado para oferecer contra-razões ao recurso interposto da rejeição da denúncia, não a suprindo a nomeação de defensor dativo.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "708", "texto": "É nulo o julgamento da apelação se, após a manifestação nos autos da renúncia do único defensor, o réu não foi previamente intimado para constituir outro.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "709", "texto": "Salvo quando nula a decisão de primeiro grau, o acórdão que provê o recurso contra a rejeição da denúncia vale, desde logo, pelo recebimento dela.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "710", "texto": "No processo penal, contam-se os prazos da data da intimação, e não da juntada aos autos do mandado ou da carta precatória ou de ordem.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "711", "texto": "A lei penal mais grave aplica-se ao crime continuado ou ao crime permanente, se a sua vigência é anterior à cessação da continuidade ou da permanência.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "712", "texto": "É nula a decisão que determina o desaforamento de processo da competência do júri sem audiência da defesa.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "713", "texto": "O efeito devolutivo da apelação contra decisões do júri é adstrito aos fundamentos da sua interposição.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "714", "texto": "É concorrente a legitimidade do ofendido, mediante queixa, e do ministério público, condicionada à representação do ofendido, para a ação penal por crime contra a honra de servidor público em razão do exercício de suas funções.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "715", "texto": "A pena unificada para atender ao limite de trinta anos de cumprimento, determinado pelo art. 75 do Código Penal, não é considerada para a concessão de outros benefícios, como o livramento condicional ou regime mais favorável de execução.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "716", "texto": "Admite-se a progressão de regime de cumprimento da pena ou a aplicação imediata de regime menos severo nela determinada, antes do trânsito em julgado da sentença condenatória.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "717", "texto": "Não impede a progressão de regime de execução da pena, fixada em sentença não transitada em julgado, o fato de o réu se encontrar em prisão especial.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "718", "texto": "A opinião do julgador sobre a gravidade em abstrato do crime não constitui motivação idônea para a imposição de regime mais severo do que o permitido segundo a pena aplicada.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "719", "texto": "A imposição do regime de cumprimento mais severo do que a pena aplicada permitir exige motivação idônea.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "720", "texto": "O art. 309 do Código de Trânsito Brasileiro, que reclama decorra do fato perigo de dano, derrogou o art. 32 da Lei das Contravenções Penais no tocante à direção sem habilitação em vias terrestres.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "721", "texto": "A competência constitucional do Tribunal do Júri prevalece sobre o foro por prerrogativa de função estabelecido exclusivamente pela constituição estadual.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "722", "texto": "São da competência legislativa da União a definição dos crimes de responsabilidade e o estabelecimento das respectivas normas de processo e julgamento.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "723", "texto": "Não se admite a suspensão condicional do processo por crime continuado, se a soma da pena mínima da infração mais grave com o aumento mínimo de um sexto for superior a um ano.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "724", "texto": "Ainda quando alugado a terceiros, permanece imune ao IPTU o imóvel pertencente a qualquer das entidades referidas pelo art. 150, VI, \"c\", da Constituição, desde que o valor dos aluguéis seja aplicado nas atividades essenciais de tais entidades.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "725", "texto": "É constitucional o § 2º do art. 6º da Lei 8024/1990, resultante da conversão da Medida Provisória 168/1990, que fixou o BTN fiscal como índice de correção monetária aplicável aos depósitos bloqueados pelo Plano Collor I.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "726", "texto": "Para efeito de aposentadoria especial de professores, não se computa o tempo de serviço prestado fora da sala de aula.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "727", "texto": "Não pode o magistrado deixar de encaminhar ao Supremo Tribunal Federal o agravo de instrumento interposto da decisão que não admite recurso extraordinário, ainda que referente a causa instaurada no âmbito dos juizados especiais .", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "728", "texto": "É de três dias o prazo para a interposição de recurso extraordinário contra decisão do Tribunal Superior Eleitoral, contado, quando for o caso, a partir da publicação do acórdão, na própria sessão de julgamento, nos termos do art. 12 da Lei 6.055/1974, que não foi revogado pela Lei 8.950/1994.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "729", "texto": "A decisão na Ação Direta de Constitucionalidade 4 não se aplica à antecipação de tutela em causa de natureza previdenciária.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "730", "texto": "A imunidade tributária conferida a instituições de assistência social sem fins lucrativos pelo art. 150, VI, \"c\", da Constituição, somente alcança as entidades fechadas de previdência social privada se não houver contribuição dos beneficiários.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "731", "texto": "Para fim da competência originária do Supremo Tribunal Federal, é de interesse geral da magistratura a questão de saber se, em face da Lei Orgânica da Magistratura Nacional, os juízes têm direito à licença-prêmio.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "732", "texto": "É constitucional a cobrança da contribuição do salário-educação, seja sob a Carta de 1969, seja sob a Constituição Federal de 1988, e no regime da Lei 9.424/1996.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "733", "texto": "Não cabe recurso extraordinário contra decisão proferida no processamento de precatórios.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "734", "texto": "Não cabe reclamação quando já houver transitado em julgado o ato judicial que se alega tenha desrespeitado decisão do Supremo Tribunal Federal.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "735", "texto": "Não cabe recurso extraordinário contra acórdão que defere medida liminar.", "vinculante": false, "pub": ""}, {"tribunal": "STF", "n": "736", "texto": "Compete à justiça do trabalho julgar as ações que tenham como causa de pedir o descumprimento de normas trabalhistas relativas à segurança, higiene e saúde dos trabalhadores.", "vinculante": false, "pub": ""}]);
